INSERT INTO `panel_app_ahadis` (`id`, `ahadis_title`, `ahadis_text_ar`, `ahadis_text_translate`, `ahadis_source`, `date_created`) VALUES
(1, 'امام صادق (ع)', '<p>إذا تَوَضَّأَ أحَدُكُم و لَم يُسَمَّ كانَ لِلشَّيطانِ فى وُضوئِهِ شِركٌ و إن أكَلَ أو شَرِبَ أو لَبِسَ و كُلُّ شَى ءٍ صَنَعَهُ يَنبَغى أن يُسَمِّى عَلَيهِ فَإن لَم يَفعَل كانَ لِلشَّيطانِ فيهِ شِركٌ؛</p>\r\n', '<p>هر گاه يكى از شما وضو بگيرد و بسم اللّه الرحمن الرحيم نگويد. شيطان در آن شريك است و اگر غذا بخورد و آب بنوشد يا لباس بپوشد و هر كارى كه بايد نام خدا را بر آن جارى سازد، انجام دهد و چنين نكند، شيطان در آن شريك است.</p>\r\n', 'محاسن ص 433 ، ح 260', '1404-01-31 00:55'),
(2, 'امیرالمومنین (ع)', '<p>ُوبَی لِمَنْ أخْلَصَ لِلَّهِ عَمَلَهُ، وَعِلْمَهُ، وَحُبَّهُ، وَبُغْضَهُ، وَأخْذَهُ، وَتَرْکَهُ، وَکَلامَهُ، وَصَمْتَهُ، وَفِعْلَهُ، وَقَوْلَهُ</p>\r\n', '<p>خوشا به حال آن&zwnj;که عمل و علمش، دوستی و دشمنی&zwnj;اش، انجام دادن و رها کردنش، سخن و سکوتش، وکردار و گفتارش را برای خدا خالص گرداند.</p>\r\n', 'بحار الأنوار، جلد 77، صفحه 289', '1404-02-02 19:06'),
(3, 'رسول خدا (ص)', '<p>إذا مٰاتَ الإنسٰانُ إنقَطَعَ عَمَلُهُ إلاّ مِن ثَلاٰثٍ: إلاّ بِصَدَقَةٍ جٰارِیَةٍ أو عِلمٍ یُنتَفَعُ بِهِ أو وَلَدٍ صٰالِحٍ یَدعوُ لَهُ</p>\r\n', '<p>با مرگ انسان عملش قطع می&zwnj;شود، مگر در سه چیز: صدقۀ ماندگار، دانشی که مردم از آن بهره&zwnj;مند شوند و فرزند شایسته&zwnj;ای که برایش دعا کند.</p>\r\n', 'میزان الحکمة، حدیث 14287', '1404-02-02 19:07'),
(4, 'امیرالمومنین (ع)', '<p>إن قارَفتَ سَيِّئَةً فَعَجِّل مَحوَها بِالتَّوبَةِ</p>\r\n', '<p>اگر به گناهى آلوده شدى، بى درنگ آن را به توبه بشوى.</p>\r\n', 'تحف العقول: ص ۸۱، حکمت نامه جوان، ص: ۱۴۶', '1404-02-02 19:09'),
(5, 'امیرالمومنین (ع)', '<p>مَا المُجاهِدُ الشَّهيدُ في سَبيلِ اللّهِ بِأَعظَمَ أجرا مِمَّن قَدَرَ فَعَفَّ</p>\r\n', '<p>کسى که در راه خدا جهاد کند و شهيد شود، اجرش بزرگ تر از کسى نيست که بتواند گناه کند و پاک دامنى ورزد.</p>\r\n', 'نهج البلاغة: الحکمة ۴۷۴، دانشنامه قرآن و حديث جلد هجدهم، صفحه: ۴۷۸', '1404-02-02 19:10'),
(6, 'امام حسین (ع)', '<p>مَن حَسُنَت خَلیقَتُهُ طابَت عِشرَتُهُ</p>\r\n', '<p>هر کس خوش اخلاق باشد، زندگى&zwnj;&zwnj;اش پاکیزه و گوارا مى&zwnj;گردد.</p>\r\n', 'نهج البلاغه، خطبه ۱۸۴', '1404-02-02 19:13'),
(7, 'امام صادق (ع)', '<p>حَسِّنْ خُلْقَکَ یُخَفِّفِ اللّه ُ حِسابَکَ</p>\r\n', '<p>اخلاقت را خوب کن تا خداوند حسابت را آسان گرداند.</p>\r\n', 'امالى صدوق، ص ۲۷۸', '1404-02-02 19:14'),
(8, 'امام رضا (ع)', '<p>أَلْمُسْتَتِرُ بِالْحَسَنَةِ یَعْدِلُ سَبْعینَ حَسَنَةً، وَ الْمُذیعُ بِالسَّیِّئَةِ مَخْذُولٌ، وَالْمُسْتَتِرُ بِالسَّیِّئَةِ مَغْفُورٌ لَهُ</p>\r\n', '<p>پنهان کننده کار نیک [پاداشش] برابر هفتاد حسنه است، و آشکارکننده کار بد سرافکنده است، و پنهان کننده کار بد آمرزیده است.</p>\r\n', 'الکافی ، ج2 ، ص428', '1404-02-02 19:16'),
(9, 'امام رضا (ع)', '<p>إن بَکَیتَ عَلَی الحُسَینِ حَتّی تَصیرَ دُموعُکَ عَلی خدَّیکَ غَفَرَاللّه ُ لَکَ کُلَّ ذَنبٍ أذنَبتَهُ</p>\r\n', '<p>اگر بر حسین بگریی، چندان که اشک هایت بر گونه ات جاری شود، خداوند تمام گناهانت را می آمرزد.</p>\r\n', 'امالی، ج 44، ص 286', '1404-02-02 19:17'),
(10, 'امام رضا (ع)', '<p>مَن جَلَسَ مَجلِسا یُحیی فیهِ أمرُنا، لَم یَمُت قَلبُهُ یَومَ تَموتُ القُلوُبُ</p>\r\n', '<p>هر که در مجلسی بنشیند که در آن یاد ما (اهل بیت) زنده می شود، قلبش، در روزی که قلب ها می میرند، نمی میرد.</p>\r\n', 'وسائل الشیعه، ج 44، ص 278', '1404-02-02 19:18'),
(11, 'امام رضا (ع)', '<p>مَن فَرَّجَ مِن مُؤمِنٍ، فَرَّجَ اللّه ُ عَن قَلبِهِ یَومَ القِیامَهِ</p>\r\n', '<p>هر کس اندوه مؤمنی را بزداید، خداوند در روز قیامت، غم از دلش می زداید.</p>\r\n', 'الکافی، ج 2، ص 200', '1404-02-02 19:19'),
(12, 'امام رضا (ع)', '<p>إذا نَزَلَت بِکم شِدَّةٌ فاستَعینوا بِنا عَلَی اللّهِ</p>\r\n', '<p>هر گاه سختی ای به شما رسید، به واسطه ما از خدا کمک بجویید.</p>\r\n', 'تفسیر العیاشی:ج2 ص176 ح1662', '1404-02-02 19:20'),
(13, 'امام حسین (ع)', '<p>مَا خَلَقَ اللّهُ مِنْ شَىْ&rlm;ءٍ إِلا وَ لَهُ تَسْبِیحٌ یَحْمَدُ بِهِ رَبّهُ</p>\r\n', '<p>امام حسین (ع) فرمود: &laquo;خداوند هیچ موجودى را نیافرید، جز آن&rlm;که براى او تسبیحى قرار داد تا با آن خدا را ستایش کند.</p>\r\n', 'بحار الانوار، ج ۶۱ ص ۲۹ ح۸', '1404-02-02 19:23'),
(14, 'امام حسین (ع)', '<p>مَنْ زَارَنِى بَعْدَ مَوْتِى زُرْتُهُ یَوْمَ الْقِیَامَهِ وَ لَوْ لَمْ یَکُنْ إِلا فِى النّارِ لاَخْرَجْتُهُ</p>\r\n', '<p>هرکه مرا پس از مرگم، زیارت کند، روز قیامت زیارتش مى&rlm; کنم و اگر در آتش هم باشد، او را بیرون مى&rlm; آورم.</p>\r\n', 'المنتخب للطریحى، ص۶۹', '1404-02-02 19:24'),
(15, 'امام حسین (ع)', '<p>خَمْسٌ مَنْ لَمْ تَکُنْ فِیهِ لَمْ یَکُنْ فِیهِ کَثِیرُ مُسْتَمْتِعٍ: اَلْعَقْلُ، وَ الدّینُ وَ الاَدَبُ، وَ الْحَیَاءُ وَ حُسْنُ الْخُلْقِ</p>\r\n', '<p>پنج چیز است که در هرکسى نباشد، خیر زیادى در او نیست: عقل، دین، ادب، حیا و خوش&rlm;خویى.</p>\r\n', 'حیاه الامام الحسین(ع)، ج ۱ ص۱۸۱', '1404-02-02 19:26'),
(16, 'رسول خدا (ص)', '<p>إنَّ الصَّدَقَة َلتُطفِئُ غَضَبَ الرَّبِّ</p>\r\n', '<p>صدقه، خشم پروردگار را فرو می&zwnj;نشاند.</p>\r\n', 'کنزالعمال، ح161143', '1404-02-02 19:28'),
(17, 'رسول خدا (ص)', '<p>اَلعِبادَهُ سَبعونَ جُزء، اَفضَلُها جُزءً طَلَبُ الحَلالِ</p>\r\n', '<p>عبادت هفتاد جزء است و بالاترین و بزرگترین جزء آن کسب حلال است.</p>\r\n', 'ثواب الاعمال و عقاب الاعمال', '1404-02-02 19:30'),
(18, 'امام حسن عسکری (ع)', '<p>جُعِلتِ الخَبائِثُ فی بَیت وَ جُعِل مِفتاحُهُ الکَذِبَ</p>\r\n', '<p>تمام پلیدیها در خانه ای قرار داده شده و کلید آن دروغگویی است.</p>\r\n', 'بحار الانوار، ج78، ص377', '1404-02-02 19:31'),
(19, 'پیامبر اكرم (ص)', '<p>هو شهر اوله رحمة و اوسطه مغفرة و اخره عتق من النار</p>\r\n', '<p>رمضان ماهى است كه ابتدایش رحمت است و میانه&rlm;اش مغفرت و پایانش آزادى از آتش جهنم.</p>\r\n', 'بحار الانوار،ج93،ص342', '1404-02-02 19:34'),
(20, 'امام رضا (ع)', '<p>من قرا فى شهر رمضان ایة من كتاب الله كان كمن ختم القران فى غیره من الشهور</p>\r\n', '<p>هر كس ماه رمضان یك آیه از كتاب خدا را قرائت كند مثل اینست كه درماههاى دیگر تمام قرآن را بخواند.</p>\r\n', 'بحار الانوار ج93، ص346', '1404-02-02 19:34'),
(21, 'امام صادق (ع)', '<p>اذا صمت فلیصم سمعك و بصرك و شعرك و جلدك</p>\r\n', '<p>آنگاه كه روزه مى &rlm;گیرى باید چشم و گوش و مو و پوست تو هم روزه &rlm;دار باشند.(یعنى از گناهان پرهیز كند.)</p>\r\n', 'الكافى ج 4 ص 87', '1404-02-02 19:36'),
(22, 'امیرالمومنین (ع)', '<p>الصلوة حصن من سطوات الشیطان</p>\r\n', '<p>نماز قلعه و دژ محکمی&nbsp;است که نمازگزار را از حملات شیطان نگاه می دارد.</p>\r\n', 'غررالحکم ، ص 56', '1404-02-02 19:39');

