INSERT INTO `panel_app_vasiatnamehshohada` (`id`, `vasiatnameh_shohada_name`, `vasiatnameh_shohada_img`, `vasiatnameh_shohada_text`, `date_created`) VALUES
(1, 'پاسدار شهید محمد بلباسی', 'imgs/vasiatnameh_shohada/954379_135.jpg', '<p>بسم الله الرحمن الرحیم</p>\r\n\r\n<p>هوالشهید</p>\r\n\r\n<p>با درود و سلام به پیشگاه امام عصر حضرت بقیه الله الاعظم روحی فداه و شهدای گرانقدر از ابتدای خلقت تا کنون خصوصا شهدای مظلوم مدافع حرم و درود به محضر معمار کبیر انقلاب اسلامی حضرت امام خمینی (ره) و رهبر عظیم الشان حضرت امام خامنه ای و آرزوی صحت و سلامت برای همه خادمین به نظام مقدس جمهوری اسلامی ایران و پیروزی همه رزمندگان جبهه مقاومت اسلامی و مدافعین حرم.</p>\r\n\r\n<p>شهادت می دهم به یگانگی خداوند و نبوت خاتم المرسلین حضرت محمد (ص) و ولایت امیرالمومنین علی ابن ابی طالب(ع) یازده فرزند معصومش. خداوند متعال را شاکرم که خلقت مرا در بهترین عصر از خلقت بشر و در بهترین سرزمین، ایران اسلامی و در استان علوی و در خانواده مذهبی و انقلابی قرار داد. آنقدر الطاف و نعمات خداوند متعال بی شمار است که انسان قادر به شمارش و شکر گذاری آن نیست</p>\r\n\r\n<p>این کمترین در اسفند ماه سال 1357 همزمان با پیروزی انقلاب اسلامی در شهرستان قائمشهر دیده به دنیا گشودم و در خانواده ای تربیت شدم که یک شهید علی عباسی را تقدیم انقلاب اسلامی و یک شهید سردار علیرضا بلباسی را تقدیم دفاع مقدس کرده و پدر مرحومم جانباز جنگ تحمیلی بود و مادرم مرا با ذکر ائمه معصومین و توسل به این چهارده نور واحد شیر داده و تبعیت و سربازی ولی فقیه حضرت امام خامنه ای جز و اصول زندگی ما بود.</p>\r\n\r\n<p>به پیشنهاد پدر عزیزم با دختری ازدواج کردم که فردی مومنه و عفیف بود که حاصل زندگی ما 3 فرزند (فاطمه، حسن، مهدی)مانند دسته گل، خداوند متعال عطا فرمود.</p>\r\n\r\n<p>در این برهه از زمان که ایران اسلامی ، ام القرای جهان اسلام شده است و مسلمانان جهان که در بند طاغوت و پادشاهی هستند با تشکیل جبهه مقاومت چشم به ایران دوختند و می خواهند از الگوی انقلاب اسلامی ایران که به رهبری حضرت امام خمینی (ره) و همراهی مردم عزیز توانستند استکبار جهانی را با دست خالی از ایران بیرون کنند، استفاده کنند و گوش بفرمان حضرت امام خامنه ای هستند و دشمنان اسلام و شیعیان ایران از این جایگاه انقلاب اسلامی هراس پیدا کرده و بدنبال گسترش اسلام آمریکایی هستند. آمریکا و هم پیمانانش با تربیت طلاب در حوزه های علمیه عربستان بدست استاتید وهابی ضد شیعه اقدام به تشکیل گروهای تروریستی برای اسلام هراسی و شیعه هراسی نموده است وبا پول نفت کشورهای عربی مسلمان که اسلامشان هیچ خطری برای استکبار ندارد، اقدام به حمایت این گروه های تروریستی نموده است. با تشکیل طالبان به جان شیعیان و اهل سنت مردم افغانستان افتاد و بسیاری از مردم این کشور را به شهادت رسانده و بسیاری را آواره کرده است. سپس با تشکیل گروه تکفیری داعش به کشور عراق حمله کرد و به فکر تجزیه آنجا بود که با دخالت و همراهی ایران اسلامی به این امر موفق نشد. سپس برای حفظ امنیت صهیونیسم جهان خوار اقدام به حمله به کشور سوریه نمود و شماری از مردم را آواره و بسیاری را به شهادت رسانده است. از طرفی هم در مقابل حزب الله لبنان و انتفاضه فلسطین و جنبهشای اسلامی کشورهای عربی به مخالفین آنها کمک نمود و بدنبال خنثی کردن این جنبش ها هستند.آمریکا و اروپا با پخش تصاویرخشونت های گروه های تروریستی و قت عام کودکان و زنان و مردان و ساخت فیلم های مبارزه با این گروه های تروریستی خود را ناجی مردم جهان معرفی کرده و به مردم خودشان چنین القاء می کنند که اگر این مسلمانان تروریست را از بین نبریم این نا امنی به اروپا و آمریکا هم سرایت می کند و با انفجار برجهای دو قلو آمریکا و عملیات انتحاری و بمب گذاری در کشور های اروپایی این رعب و وحشت را بر علیه مسلمانان ایجاد می نمایند و با سانسور رسانه ای از آگاهی مردم به واقعیت جلوگیری می کند و ایران را فتنه همه این اتفاقات معرفی نموده است.</p>\r\n\r\n<p>الحمدالله با درایت رهبر عظیم الشان ایران اسلامی که دائما بدنبال معرفی چهره خبیث و شیطانی استکبارکه جهانی می باشد که این نقاب دروغین دفاع از حقوق بشر را از چهره آنان بر دارد و با ارسال نامه به جوانان اروپایی آنان را نسبت به اتفاقات منطقه آگاه نماید. اکنون با تدبیر معظم له ایران حضور مستشاری در بعضی از کشور های اسلامی به فریاد مسلمانان رسیده ودر این مسیر تعدادی شهید تقدیم کرده است و علت حضور مستشاری این کمترین در سوریه بعنوان مدافع حرم لبیک به امر رهبرم بوده است و مطمئنا جوانان ایران اسلامی نخواهند گذاشت دست این نا اهلان به حرم اهل بیت سلام الله علیهما برسد و با عنایت خداوند متعال و یاری امام عصر انشاالله همه این تروریستها را نابود خواهیم کرد.</p>\r\n\r\n<p>مردم عزیز آگاه باشید اکنون دشمن با نقاب اسلام به میدان مبارزه با ما به میان آمده است و این اتفاق ریشه تاریخی دارد و در زمان امیرالمومنین در جنگ صفین با نقشه عمرو عاص ملعون ، خوارج قرآن را به نیزه کردند و با گفتن لا اله الا الله و محمد رسول الله یاران حضرت علی (ع) را فریب دادند و اصحاب امام را تنها گذاشتند و گفتند ما با قرآن نمیجنگیم و از حیله دشمن غافل شدند و قرآن ناطق را رها کردند و اکنون بعضی ها در داخل دارند این حرفها را تکرار می کنند وما را متهم به بردارکشی می کنند و حضور در این جبهه را باطل می دانند.اما زهی خیال باطل که دوباره تاریخ تکرار و جوانان نسل سوم و چهارم گوش به فرمان رهبر هستند و نخواهند گذاشت پای آنها به مرزهای کرمانشاه و همدان برسد و در این مسیر هم جوانان عزیزی بعنوان مدافع حرم اهل بیت به شهادت رسیدند که در حقیقت مدافع اسلام و مدافع دین خدا هستند و شهادت در این راه برای ما افتخار است.</p>\r\n\r\n<p>و حالا چند کلامی با همسر عزیزم و فرزندان دلبندم:</p>\r\n\r\n<p>همسر وفادار ومهربانم سلام ، خدا را گواه میگیرم که اگر نبود همراهی و همدلی شما بنده به این سعادت دست پیدا نمیکردم. بارها شما آزموده شدید و در سخت ترین شرایط با تمامی کمی و کاستی ها با من همراه بودی و هیچ وقت در انجام کار خیر مانع من نشدی و حتی مرا تشویق به انجام آن کردی . در صورتی که این همراهی شما سختی زیادی بهمراه داشت و دوری من از خانه خللی در زندگیمان ایجاد نکرد و مانند یک شیر زن امورات منزل را رتق و فتق کردی و هر سه فرزندمان را به نحو شایسته تربیت کردی و تنها نگرانی شما کسب حلال و آوردن لقمه حلال برسر سفره بود و بود و مرا توصیه به تقوی و دوری از گناه می کردی و هیچ وقت از من راحتی و آسایش دنیا را نخواستی و همیشه به آسایش و راحتی خودمان و فرزندانمان بودی. با اینکه تازه از ماموریت تقریبا یک ماهه جنوب برگشته بودم و بعد از 4 شب ساعت 10 شب مطلع شدم باید به سوریه عازم شوم و این موضوع را به شما گفتم، شما لحظه ای درنگ نکردی و فرزند در راهمان هم مانع رفتن من نشد و با روی گشاده از رفتن من برای دفاع از حرم خضرت زینب (س) استقبال کردی. این هم آزمون دیگری بود که باز هم شما سربلند ازآن بیرون آمدی. همسر عزیزم مطالبی که عرض کردم گوشه ای از دریای خوبیها و عشق و محبت شمابود.</p>\r\n\r\n<p>الان که دارم این وصیتنامه را می نویسم خیلی دلتنگ شدم و گریه امانم نمیدهد، بنده لایق شهادت نیستم اما اگر خداوند متعال به این کمترین عنایتی بکند و مرگ مارا شهادتت در راهش رقم بزند آنرا مدیون تو هستم. وعده ما انشاء الله در محضر بی بی زینب (س) و ائمه معصومین. برای تو صبر زینبی را آرزو میکنم از طرف من روی فرزندانم را ببوس و به فرزند چهارم بگو این سختیها، آسایشی بهمراه خواهد داشت و دلتنگ بابا نباشد.</p>\r\n\r\n<p>فاطمه جونم دختر بابا سلام، اگر دوست داری باز هم همدیگه رو ببینیم باید ظاهرت مثل باطنت اسلامی و قرآنی باشد. مانند مادرت محجبه و عفیف باش. در مقابل سختی ها صبور باش.</p>\r\n\r\n<p>حسن جون ، مهدی جون، سلام.</p>\r\n\r\n<p>حالا بعد از بابا مرد خونه شما هستید مواظب مادر و خواهرتون باشید که احساس تنهایی نکنند. خویشتندار باشید و احساس غریبی نکنید.</p>\r\n\r\n<p>فرزندانم گلم نماز که ستون خیمه دین است را سبک نشمارید . احترام به مادر از واجبات شماست، در محضر روحانی حقیقی زانو بزنید و درس دین بیاموزید.</p>\r\n\r\n<p>آخرت خود را به دنیای فانی نفروشید، کمک به مستمندان و محرومین را فراموش نکنید. در عرصه های اجتماعی، فرهنگی و سیاسی حضور فعال داشته باشید. گوش به فرمان ولی فقیه زمان خود باشید. ادامه دهنده راه شهدا باشید ، نگذارید این علم به زمین بیافتد. خوش خلق و مودب باشید. به هم دیگر محبت کنید، صله رحم را بجا آورید و قطع رحم نکنید.</p>\r\n\r\n<p>حالا چند کلامی با خانواده ام:</p>\r\n\r\n<p>مادر مهربان سلام، فقط بگویم از جبران زحماتی که برای من کشیدی عاجزم . ممنون شما و پدر مرحومم هستم که با سختی و مشقت فراوان موجبات آسایش و راحتی ما را فراهم کردید و با کسب حلال و شیر پاک ما را در مکتب ائمه معصومین تربیت کردید. متاسفانه به هنگام رفتن فرصت دست بوسی پیدا نکردم و از همین جا کف پایت را می بوسم. از اینکه راضی به آمدن من به این سفر بودی ممنونت هستم و از خداوند متعال صب جزیل را برای شما آرزومندم. امیدوارم که مزد زحمات خود را از حضرت زینب (س) بگیری.</p>\r\n\r\n<p>و اما برادر و خواهر گرامیم:</p>\r\n\r\n<p>الحمدالله همه شما در دامن پدر و مادری تربیت شدید که متخلق به اخلاق اسلامی هستید. دنیا محل گذر است، ابد در پیش دارید و به فکر توشه ی آخرت باشید. در برابر مصائب و مشکلات خویشتن دار باشید. من هر چه دارم از دعای خیر پدر و مادر است. برادر عزیزم لحظه ای از مادر غافل نشو. نهایت احترام را به او بگذار و مثل کوه پشت سر ایشان بایست. انجام واجبات ، ترک محرمات و کسب حلال را سر لوحه س زندگیت قرار بده. ادامه دهنده را شهدا باش و گوش به فرمان رهبر باش. جای خالی پدر را برای فرزندانم پر کن.</p>\r\n\r\n<p>از همه فامیل ها، عمو، دایی، عمه، خاله، دامادها و خواهر زاده ها و برادرزاده ها و دیگر فامیل ها طلب حلالیت دارم. اگر قصوری از این حقیر سر زده از همه شما طلب حلالیت دارم. امیداوارم مرا به بزرگی خودتان عفو بفرمائید.</p>\r\n\r\n<p>اما توصیه به همکارانم:</p>\r\n\r\n<p>خدارا شاکرم که لباس سپاه را بر تن کردم و با بهترین ها همکار بودم و لحظه ای از کار کردن در سپاه پشیمان نیستم و به آن فخر میکنم. همکاران عزیزم، سپاه یک نهاد انقلابی است قدر آن را نمی شود با حقوق و مزایای ماهیانه مشخص کرد. این نهاد به قیمت خون شهدا و ایثارگریِ ، ایثارگران شکل گرفته و اگر کسی به نگاه شغل و کسب درآمد ماهیانه به این نهاد پا گذاشته باید نگاه خود را اصلاح کند، یا باید از این نهاد خداحافظی کند، وگرنه خون به خون شهدا خیانت خواهد کرد.</p>\r\n\r\n<p>دشمنان این نظام به سپاه چشم طمع دوخته اند، زیرا سپاه خار چشم دشمنان شده است و میخواهند با دنیا طلبی و اشرافیگری مارا خثی کنند.</p>\r\n\r\n<p>همکاران عزیز، هوشیار باشید، گوش به فرمان فرمانده کل قوا باشید.</p>\r\n\r\n<p>از همه همکارانم، خصوصا بسیجیان عزیز که در ماموریت های مختلف اروهای جهادی، اردوهای راهیان نور، این حقیر را همراهی کردند، صمیمانه قدرشناسی میکنم. اگر اشتباهی از این کمترین سر زده از همه شما عذر خواهم.</p>\r\n\r\n<p>در پایان اگر دوستان و همکاران و بستگان از من حقیر طلبی دارد، میتواند به خانواده ام مراجعه نماید و آن را وصول نماید.</p>\r\n\r\n<p>اگر امکانش هست، مرا در گلزار شهدای ملال در جوار عموی یا پدر عزیزم به خاک بسپارید.</p>\r\n\r\n<p>محمد بلباسی</p>\r\n\r\n<p>17 رجب 1437</p>\r\n\r\n<p>8 اردیبهشت1395</p>\r\n', '1404-02-03 00:34'),
(2, 'شهید رضا حاجی زاده', 'imgs/vasiatnameh_shohada/download.png', '<p>((و اما خاف مقام ربه و نهی النفس عن الهوی فان الجنه هی الماوی)) آیات 40 و41 سوره مبارکه النازعات</p>\r\n\r\n<p>و اما آن کس که از مقام و مرتبه پروردگارش ترسیده و خودرا از هوا و هوس بازداشته است به یقین بهشت جایگاه اوست.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>با سلام و صلوات به محضر منجی عالم بشیریت حضرت صاحب الزمان (عج) و نائب بر حقش امام خامنه ای و شهدای اسلام و ایران ، به خصوص شهدای مدافع حرم،</p>\r\n\r\n<p>اینجانب رضا حاجی زاده فرزند رجبعلی در صحت و سلامت کامل عقلی وصیت نامه خود را می نویسم.</p>\r\n\r\n<p>من نمیخواهم که عمر بی ثمر باشد، و مرگم یک مرگ عادی ، مرگی میخواهم که در راه اسلام و ایران اسلامی باشد.</p>\r\n\r\n<p>من بخاطر منطق خویش برای دفاع از اسلام و حریم اهل بیت (ع) وارد جنگ با دشمنان اسلام شدم و با عشق و علاقه و رضایت کامل جان خویش را فدای این راه می نمایم و میروم تا انتقام سیلی حضرت زهرا (س) را بگیرم.</p>\r\n\r\n<p>من از مردم ایران میخواهم تفرقه اندازی نکنید، با هم متحد باشید دین اسلام را سربلند نگه دارید. به دوستان و آشنایان توصیه میکنم نماز اول وقت و با حضور قلب بخوانید.</p>\r\n\r\n<p>پدر ومادررا گرامی و محترم بدارید، از طهارت و معصومیت خود شدیدا حراست و پاسداری کنید، پیوند به ائمه اطهار (ع) و بخصوص امام هشتم را مستحکم کنید،و خدای متعال و مهربان را در همه حال به یاد داشته باشید.</p>\r\n\r\n<p><strong>خدمت پدر و مادر عزیز و گرامی:</strong></p>\r\n\r\n<p>موفقیت من درمراحل گوناگون زندگی مرهون زحمات و دعای خیرتان بوده است، امیدوارم کوتاهی و قصورم را در رسیدگی به اوضاع و احوالتان بخشنده باشید و حلالم کنید و این را بدانید تا آنجا که در توان داشتم در حد بضاعتم تلاش کردم تا رضایت شما را در زندگی خود داشته باشم.</p>\r\n\r\n<p>هر پدر و مادری عاقبت به خیری فرزندشان را خواهانند و این را بدانید که بنده عاقبت به خیر شدم و این عاقبت به خیری را مدیون زحمات دیروز شما هستم.</p>\r\n\r\n<p><strong>داداش جان:</strong></p>\r\n\r\n<p>در نبود من پدر و مادر را فراموش نکن و همواره تابع بی چون و چرا ولایت باش، دشمن همواره از دینداری و ولایت پذیری تو هراس دارد، پس کاری کن که دشمن همواره از تو و امثال تو بترسد.</p>\r\n\r\n<p><strong>همسرمهربان و صبورم:</strong></p>\r\n\r\n<p>می دانم که بعد از رفتن من تمام سختی های این زندگی بر دوش توست، من برای شهادت نمی روم، من جوانم و زندگی با شما را دوست دارم و میخواهم با شما باشم، ولی این تکلیف ماست که از حریم اسلام و اهل بیت دفاع کنیم و راضی هستیم به رضا خدا، ولی این بار سنگین بر دوش توست و از تو میخواهم صبر زینب گونه پیشه کنی، و در برابر تمام سختی ها و مشکلات یاد خدا را فراموش نکنی و در تمام مراحل از خدا کمک بگیری، از تو میخواهم که فرزندانم را طوری تربیت کنی که در مسیر اسلام ولایت ادامه دهنده را شهدا باشند و بابت تمام کمبودها و نبودهایم از تو میخواهم حلالم کنی.</p>\r\n\r\n<p><strong>فاطمه حلما جان:</strong></p>\r\n\r\n<p>دتربابا، دوستت دارم، دوستت دارم ، بدان که بابا رفته است که تا تو و امثال تو در امنیت و آرامش در خاک خود قدم بگذارید و بدان که ناموس شیعه در واقع ناموس خودمان است، تکلیف ما این است که از ناموس شیعه دفاع کنیم و جان خود را در این راه بدهیم و از تو میخواهم که در سنگر خود که همان چادر توست بمانی و بایستی و مقابله کنی تا پرچم اسلام و تشیع همیشه پیروز و سرافراز بماند.</p>\r\n\r\n<p><strong>محمد طه جان:</strong></p>\r\n\r\n<p>مرد خانه بابا، تو دیگر ستون خانه ای ، از تو میخواهم که دینت را حفظ کنی و در خط ولایت فقیه باشی و گوش به فرمان رهبر عزیزمان باشی ، دعا میکنم که در رکاب امام زمان (عج) ادامه دهنده را شهدا باشی و در زندگیت طوری باشی که موضع اسلام و مسلمین به خطر نیفتد.</p>\r\n\r\n<p>ازهمه دوستان و آشنایان و همکارانم میخواهم که مرا حلال کنند و قصورم را ببخشند و اگر دینی از کسی برگردنم مانده است برای تسویه به خانواده ام مراجعه نمایند که خداوند میفرمایند هر گناهی از شما بخشیده میشود غیر از حق الناس</p>\r\n\r\n<p>من الله توفیق</p>\r\n\r\n<p>رضا حاجی زاده</p>\r\n\r\n<p>1395/01/30</p>\r\n', '1404-02-03 13:01'),
(3, 'شهید مصطفی زال نژاد', 'imgs/vasiatnameh_shohada/1395122318041120810268924.jpg', '<p>شهید مصطفی زال نژاد (۱۳۶۰ آمل _ ۱۳۹۵ سوریه) متولد شهرستان آمل در استان مازندران است. ایشان در خانواده&zwnj;ای با ایمان و دوستدار اهل بیت علیه &zwnj;السلام متولد شد، مادرش نجیبه ادهمی و پدرش محمد نام داشت.</p>\r\n\r\n<p>مصطفی زال نژاد در سایه محبت های پدر و مادر پاکدامن و مهربانش دوران کودکی را پشت سر گذاشت و بعد وارد مدرسه شد و به فراگیری تحصیل پرداخت، تحصیلات را در مقطع ؟ به پایان رساند .شهید بزرگوار متاهل و فرزند ؟ خانواده بود.</p>\r\n\r\n<p>مصطفی زال نژاد عضو رسمی سپاه پاسداران انقلاب اسلامی بود و در لشکر ۲۵ کربلا و در رسته پیاده به اسلام خدمت می کرد که در ۱۳۹۵/۱۱/۲۶ هجری شمسی در منطقه سوریه / درعا شهد شیرین شهادت نوشید و در جوار رحمت الهی جای گرفت. پیکر پاک این شهید عزیز پس از تشییع در گلزار شهدای امامزاده ابراهیم امل به خاک سپرده شد. سلام و درود خدا بر روح پاک و مطهرش.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>اللهم اجعَل مَحیایَ مَحیا مُحَمَّدٍ و آلِ مُحَمَّد و مَماتی مَماتَ مُحمَّدٍ و آلِ محمد</p>\r\n\r\n<p>پروردگارا قرار ده زندگیم را [۱] محمد و آل محمد و مرگم را مرگ محمد و آل محمد.</p>\r\n\r\n<p>اینجانب مصطفی زال نژاد فرزند کوچکی از امت حزب الله ایران با شهادت به وحدانی و رسالت پیامبران و با علم به اینکه شهادت فوزی عظیم است، پای در این واده نهاده به عشق خداوند و با توفیقی که خداوند بزرگ نسبت به بنده خود کرده است به خدمت اسلام مشغول و با بصیرت و آگاهی کامل وصیت خود را می&zwnj;نویسم. سلام بر رهبر عزیز انقلاب حضرت آیت الله خامنه&zwnj;ای، سلام بر شهیدانی که با نثار خون خود درخت پربرکت اسلام را آبیاری کردند. درود بر شهیدان و بر روحانیت و مردم مبارز. سلام بر آن&zwnj;ها که رهبر خود را در تمام مدت تنها نگذاشته و همواره پیرو خط ولایت فقیه بودند و سلام به همه&zwnj;ی دوستان هیئتی و مذهبی که عمریست در مکتب سیدالشهدا عرض ادب می&zwnj;کنند. امیدوارم که تا عمر باقیست، دست از این مسیر برندارید انشالله.</p>\r\n\r\n<p>خدایا! من آن بنده توام که روزی قابل ذکر نبودم و تو با عنایت خودت مرا به وجود آوردی و با ایمانی که به من دادی بر من بزرگواری کردی، با نعمت&zwnj;های بیشمار بر من تفضل کردی. خدا را صد هزار مرتبه شکر اعتراف می&zwnj;کنم هر چیزی که در این دنیا دارم (عزت، آبرو، همسر، فرزند، کارم و ...) همه از در خانه اهل بیت و سیدالشهداست. گاهی در مراسمات هیئت در روضه سیدالشهدا در حال گریه از خدا عاقبت به خیری طلب می&zwnj;کردم که شهادت خود نیز عاقبت به خیری است. چه بگویم ای خدا واقعاً رویم سیاه است. چقدر در حرم سیدالشهدا که چهار بار توفیق زیارت را پیدا کردم و همین طور در حرم امام رضا (ع) از تو طلب عفو و بخشش کردم و با خود گفتم دیگر مرتکب گناه نمی&zwnj;شود اما به قول خود پایبند نبودم و باز مرتکب اعمال ناشایست می&zwnj;شدم. ای خدا اگر گناهی از من سرزده از روی جهالت من است نه اینکه از درگاه تو خارج شوم هرگز، هر چه به خودم نگاه می&zwnj;کنم می&zwnj;بینم همه&zwnj;ی کارهایی که در زندگیم انجام داده&zwnj;ام برای رضای خدا نبوده بلکه برای خودنمایی و نشان دادن بوده است. خدایا! خودت دست&zwnj;گیری کن به حق خانم حضرت زهرا (س)</p>\r\n\r\n<p>ای ملت بدانید امروز مسئولیتتنان بزرگ و بارتان سنگین است از شما مردم مسلمان و دوستان تقاضا می&zwnj;کنم که با انقلاب به حالت سستی برخورد نکنید. انقلاب هدف بزرگی را دنبال کرده است. باید کار جهادی صورت گیرد و آن هم احیای ارزش&zwnj;های اسلامی است. می&zwnj;خواهم بگویم که زمانی در اوایل انقلاب جنگ ما در مرزهای سرزمین ایران بوده است ولی الان فراتر رفته است و تا مرزهای فلسطین، لبنان، سوریه حتی خود آمریکا رسیده است. بزرگ&zwnj;ترین دشمن ما آمریکاست که شیطان بزرگ است. مردم عزیز بدانید بزرگ&zwnj;ترین نعمت امنیت است برای خانواده&zwnj;ها. ما حاضریم گرسنگی بکشیم و سختی و تحریم را تحمل کنیم ولی زیر بار زور نمی&zwnj;رویم. این درس را از سیدالشهدا آموختیم. در آخرین لحظات عمر سیدالشهدا دشمن وقتی به خیمه&zwnj;ها حمله کرد، ابی&zwnj;عبدالله تمام توان خود را گذاشت و بلند شد و گفت: تا زمانی که من زنده هستم، به حرم من حمله نکنید. آری؛ حسین غیرت الله است. نامرد دستور داد اول کار حسین را تمام کنید، بعد به خیمه&zwnj;ها حمله کنید. این یک درس است برای همه&zwnj;ی مسلمانان.</p>\r\n\r\n<p>امروز بزرگ&zwnj;ترین جنگ ما مقابله با تهاجمات فرهنگی است. روز مصیبت ما آن زمانی است که چادر از سر زنان و دختران ما کنار برود و ماهواره بر سر در همه&zwnj;ی خانه&zwnj;ها علم شود. وای بر آن روز که موجب بی&zwnj;حیایی در خانواده&zwnj;ها می&zwnj;شود. در این مدت وقتی خبر شهادت چند تن از دوستان همکارم را شنیدم، فهمیدم که همچنان در باغ شهادت باز است.</p>\r\n\r\n<p><strong>صحبتی با پدر و مادر عزیزم:</strong></p>\r\n\r\n<p>پدر و مادر مهربانم از شما خواهش دارم که فرزند حقیر خویش را حلال کنید. پدر و مادر گرامی می&zwnj;دانم که چه زحمت&zwnj;هایی برای من کشیده&zwnj;اید و اگر تا آخر عمر خواسته باشم زحمات شما را جبران کنم نمی&zwnj;توانم. پدر و مادر عزیزم از شما خواهش دارم و آن این است که برای فرزند گنهکار خویش حلالیت طلبید و هر کس طلبی از من دارد به او بپردازید و به تمام فامیل و دوستان بگویید که هیچگونه ناراحت نباشند و از آن&zwnj;ها بخواهید من گنهکار را حلال کنند. پدر، مادر، خواهر و برادرم وظیفه&zwnj;ی خود را در حد واجب کفایی انجام داده&zwnj;اید ولی این را فراموش نکنید که هنوز دین خود را به اسلام ادا نکرده&zwnj;ایم. مواظب باشید با افرادی که جنگ را تحریم می&zwnj;کنند و لاف حمایت از اسلام را می&zwnj;زننند، تماس نداشته باشید که به خدا سوگند این&zwnj;ها همه دروغگویند و خائن به اسلام هستند. پدر و مادرم از خداوند منان می&zwnj;خواهم که صبری جمیل به شما عطا بفرماید و مواظب همسر و فرزندانم باشید. نگذارید به آن&zwnj;ها بعد از من سخت بگذرد.</p>\r\n\r\n<p><strong>صحبتی با همسر عزیزم</strong></p>\r\n\r\n<p>همسر خوبم باید علاوه بر تقویت ایمان خود با تجهیز بیشتر علم مبارزه را فرابگیرید و با اتکال به قدرت عظیم خداوند خود را برای نبردی طولانی آماده سازید. این مبارزه مستقیماً با دشمن است. خواه در آن&zwnj;جا با افراد کج&zwnj;اندیش و کوته&zwnj;نظر، خواه با افراد نادان و جاهل، خواه با کسانی&zwnj;که می&zwnj;خواهند انقلاب را تضعیف کنند، خواه در فامیل و خانواده باشند. به هر صورت فرقی نمی&zwnj;کند زیرا اسلام اقتضا می&zwnj;کند که چنین باشد و هر کجا اسلام در خطر است، شما هم باید در صحنه باشید. همسرم می&zwnj;دانی دوست دارم همیشه نزد تو باشم و زندگی خوبی که در توان دارم، برایت فراهم کنم ولی چه کار کنم قبل از اینکه همسر تو باشم، بنده&zwnj;ی خدا هستم و باید خدا را راضی کنم که رضایت او انشالله رضایت بنده&zwnj;اش است. تشکر می&zwnj;کنم از همسر عزیزم که طی این چند سال زندگی مشترک، دوری من و سختی&zwnj;ها را تحمل کرده است. می&zwnj;دانم بعد از من زندگی برایت سخت می&zwnj;شود. امیدوارم که مزدت را از خانم حضرت زهرا (س) دریافت کنی. امیدوارم در این راه صبر زینبی پیشه کنی و مانند زینب (س) پیام رسان باشی و همیشه ذاکر خدا باشی.</p>\r\n\r\n<p><strong>خدیجه جان!</strong></p>\r\n\r\n<p>در این دنیا فقط پاکی، صداقت، ایمان، محبت به مردم، جان دادن در راه خدا و عبادت باقی می&zwnj;ماند. تا می&zwnj;توانی به مردم کمک کن. مواظب دختر و پسرمون باش.</p>\r\n\r\n<p><strong>چند نکته به همسر عزیزم خدیجه!</strong></p>\r\n\r\n<p>۱. می&zwnj;دانم در حق شما مدام ظلم کرده&zwnj;ام، بداخلاقی کرده&zwnj;ام و وظیفه&zwnj;ام را به جا نیاورده&zwnj;ام ولی یقین بدان که خود را بنده&zwnj;ای قاصر و کم&zwnj;کار می&zwnj;دانم و امیدوارم که حلالم کنید.</p>\r\n\r\n<p>۲. دختر و پسرمون امانت&zwnj;هایی هستند در دست تو و مدام باید در تربیت اسلامی آن&zwnj;ها همت گماری.</p>\r\n\r\n<p>۳. فرزندان ما را با قرآن بیشتر آشنا کن و همواره دست آن&zwnj;ها را بگیر و در مراسمات سیدالشهدا حضور داشته باشید که عاقبت به خیری در این مراسمات است.</p>\r\n\r\n<p>۴. بعد از شهادت من گریه نکن و لبخند بزن و بگو مثل خانم حضرت زینب (س) در طی این دوره من هر چه دیدم زیبایی بود و این سختی&zwnj;های تو بالاتر از خود شهادت است.</p>\r\n\r\n<p><strong>صحبتی با دختر و پسر عزیزم</strong></p>\r\n\r\n<p>۱. انشاءالله وقتی به سنی رسیدید که تواستید این وصایا را درک نمایید هر چند روز یک بار این وصیتنامه را بخوانید.</p>\r\n\r\n<p>۲. شناخت کامل در حد استطاعت خود از خداوند متعال پیدا نمایید. در پی اصول اعتقادی تحقیق و مطالعه نمایید و تفکر زیاد نمایید تا به اصول اعتقادی یقین کامل داشته باشید.</p>\r\n\r\n<p>۳. احکام اسلامی را با تعبد کامل و به طور دقیق و با معنی به جا آورید.</p>\r\n\r\n<p>۴. قرآن بخوانید و زیاد تفکر کنید در معنای قرآن.</p>\r\n\r\n<p>۵. از راحت&zwnj;طلبی و به دست آوردن روزی به طور ساده دوری نمایید. دائم باید فردی پرتلاش و خستگی&zwnj;ناپذیر باشید.</p>\r\n\r\n<p>۶. قدر این انقلاب اسلامی را بدانید و زندگی خود را صرف تحکیم پایه&zwnj;های این جمهوری قرار دهید.</p>\r\n\r\n<p>۷. دست از مراسمات هیئت و اهل بیت (ع) برندارید زیرا هر چه بخواهید در درِ خانه&zwnj;ی اهل&zwnj;بیت و سیدالشهداست.</p>\r\n\r\n<p>۸. پسر عزیزم باید در خانه جای خالی پدر را پر کنی و همواره مواظب مادر و خواهرت باشی.</p>\r\n\r\n<p>۹. بر حذر باشید از وسوسه&zwnj;های نفس و مدام به یاد خدا باشید تا از شر نفس و شیطان در امان باشید.</p>\r\n\r\n<p>۱۰. حرف آخر وصیتی از مرحوم حضرت آیت الله خوشوقت که در زندگیم خیلی کمک حال من بوده. ایشان بیشتر مواقع می&zwnj;فرمودند تقوا را رعایت کنید یعنی ترک محرمات و انجام واجبات. اگر رعایت شود به مقامات عالیه می&zwnj;رسید. دیگر احتیاج به چله&zwnj;نشینی و ... نیست.</p>\r\n\r\n<p><strong>صحبتی با دوستان</strong></p>\r\n\r\n<p>از شما دوستان عزیز می&zwnj;خواهم که حلال کنید. از برادرانی که به هر دلیل از هیئت جدا شدن می&zwnj;خواهم که برگردن به قبل خود و تنها این را می&zwnj;خواهم بگویم که عمر کوتاه است. معلوم نیست که سرنوشت ما چه خواهد شد. مرگ ما کی فرامی&zwnj;رسد. نکند که در آن دنیا شرمنده&zwnj;ی سیدالشهدا شویم. و از دوستان هیئتی می&zwnj;خواهم که الان باید در زمینه&zwnj;ی هیئت و سیدالشهدا کار جهادی کرد. فقط حرف زدن نیست. باید عمل باشد. خیلی&zwnj;ها به علت کار و زندگی از ابی عبدالله جدا شدند و فقط در محرم عرض ادب می&zwnj;کنند بلکه سیدالشهدا برای تمام فصول سال است. از برادران مداح هیئت می&zwnj;خواهم در زمینه&zwnj;ی مداحی باید کار حرفه&zwnj;ای کرد. مطالعه انجام شود، شعر حفظ کنید. حتماً باید از محضر استاد استفاده کرد. بنده خیلی شعر حفظ کردمو در تهران که بودم از محضر اساتید زیادی بهره بردم مثل حضرت آیت الله خوشوقت. کلاس حاج سعید حدادیان در دانشگاه تهران، حاج مهدی سماواتی و استاد سازگار ولی به دلیل شغلم و نبودن من در هیئت نتوانستم خوب کار کنم زیرا لازمه&zwnj;ی یک مداح خواندن زیاد در مراسمات مذهبی است. دوستان در خواندن زیارت عاشورا شهدا را فراموش نکنید.</p>\r\n\r\n<p>در پایان از خداوند می&zwnj;خواهم که ما را مشمول کرامت خود گرداند. از همه می&zwnj;خواهم که این نهضت را حفظ کنید و همیشه به یاد شهدا باشید. قدر رهبر انقلاب را بدانید و خالصانه پیروش باشدی. این انقلاب اسلامی امانت الهی است. وظیفه&zwnj;ی همه&zwnj;ی ما پاسداری از انقلاب و دستاوردهای آن است. صلاح دنیا و آخرت ما در پیروزی از ولایت فقیه می&zwnj;باشد. انشاءالله که خداوند متعال با رحمت و بزرگواری خود گناهان بی&zwnj;شمار این بنده&zwnj;ی خطاکار را ببخشد.</p>\r\n\r\n<p>اَلّلهُمَّ ارزُقنی شَفاعَة الحُسین یَومَ الورودِ و ثَبِّت لی قَدَمَ صِدقٍ عِندک مَعَ الحُسینِ.</p>\r\n\r\n<p>پروردگارا شفاعت حسین را روزی که برتو وارد می&zwnj;شوم، نصیبم بگردان و مرا نزد خود ثابت قدم بدار سیدی و مولا یا حسین</p>\r\n\r\n<p>مصطفی زال&zwnj;نژاد مصادف با میلاد امام زمان (عج الله)</p>\r\n\r\n<p>سال ۱۳۹۲</p>\r\n', '1404-02-03 13:36'),
(4, 'شهید روح الله صحرایی', 'imgs/vasiatnameh_shohada/images.jpeg', '<p>با سلام و درود به پیشگاه حضرت حق و محضر ولی عصر (عج) و نائب بر حقش حضرت امام خامنه ای ( دامت برکاته) و به ارواح ملکوتی امام خمینی (ره) و همه شهدای راه حق.</p>\r\n\r\n<p>اینجانب روح ا... صحرایی فرزند غلامرضا، وصیت نامه ی خود را در طی 2 قسمت می نویسم:</p>\r\n\r\n<p>قسمت اول مربوط به خانواده و قسمت دوم خدمت فامیل ها و دوستان و آشنایان ، هم محله ای ها و همکاران عزیز می باشد.</p>\r\n\r\n<p><strong>قسمت اول:</strong></p>\r\n\r\n<p>پدر عزیزم، مادر دلسوزم ، همسر صبورم و برادر مهربانم ، من با اشک چشم و دلی شاد از نزد شما به محضر الهی می روم. جسم من می رود ولی روح من در کنار شماست، پس بر من گریه نکنید، چون که من نمرده ام، بلکه زنده ام و شما را می بینم. من و امثال من هدیه و نعمتی هستیم که خداوند به هر پدر و مادری می دهد و شماها مرا به نزد عزیز دلم خداوند بلند مرتبه فرستادید و من در راه حق رفتم و در محضر او به آرامش دل رسیده ام. شماها هم برای اینکه این فراق جسمانی مرا تحمل کنید و برایتان آسان شود، بیاد آورید کربلا را ، صبوری و استقامت حضرت زینب (س) را ، برادران و برادرزادگان و پسران خود را به میدان نبرد فرستاد و جلوی چشم آن حضرت همه شهید شدند و سرمبارکشان بالای نیزه رفت. بیاد بیاورید امام حسین (ع) و سرگذشت آن حضرت را ، من بیچاره که آبرومند و سربلند رفتم و با عزت و احترام بر می گردم. من در محضر خداوند و امام حسین (ع) شرمنده ام که چرا یکبار برایشان جان می دهم و چرا دیر.</p>\r\n\r\n<p>نماز و حجاب خود را حفظ کنید و برای خدا زندگی کنید و همیشه بیاد خدا باشید. فرزندانم را طوری تربیت نمایید که پرچم دار راه شهیدان باشند تا ان شاا... در ظهوری نزدیک در زمره سربازان واقعی امام زمان (عج) قرار گیرند.</p>\r\n\r\n<p><strong>قسمت دوم:</strong></p>\r\n\r\n<p>خدمت همه فامیل ها و دوستان و آشنایان، هم محله ای ها و همکاران عزیز، اولا بگویم که این وصیت نامه ، صرف نصیحت به شما نیست، بلکه تذکر خودم نیز می باشد. خیلی سخت است برای من نوشتن این چند جمله ، چون حرف دل را در محضر خداوند نمی توان روی کاغذ آورد و بیان کرد. حرف درل را باید فقط به محضرش گفت، چون عاشق واقعی اوست. اگر می خواهید زندگی کنید، برای خدا زندگی و اگر خواستید بمیرید برای خدا و در راه او جان بدهید. متوسل به عشق الهی شوید، این عشق پایدار است و آرامش بخش می باشد. هم در این دنیا و هم در آخرت در محضرش، عشق زمینی ، هدیه و نعمت و رحمت عشق الهی است. عاشق مطلق خداست و بعد پیامبرانش و بعد معصومین(ع) ، چون خود خداوند می فرماید: من از رگ گردن به شما نزدیکترم ، من دوست دارم دست شما را بگیرم و بسوی خود باز گردانم و به شما آرامش دهم، می فرماید: پس چرا قدر این عاشق بی نیاز و بی توقع را نمی دانید. حالا من بیچاره در محضر خدا کجا هستم و شما ای عزیزانم کجا هستید و به کجا می روید، به حال و احوال خود بنگرید تا متوجه شوید کجای کارید.</p>\r\n\r\n<p>ای عزیزانم، خدارا، خدارا، فراموش نکنید، رسم این عشق و عاشقی ا بین خود و خدای خود بهم نزنید، تا زنده اید خدا منتظر شماست و بدانید کسی که برای خدا و در راه خدا مرده است، نمرده است ، بلکه زنده است و در محضر الهی تا ابد می ماند.</p>\r\n\r\n<p>برای ما گریه نکنید، ما زنده ایم و در محضر خدایم ، برای مصیبت امام حسین (ع) گریه کنید.</p>\r\n\r\n<p>توصیه من این است که دست از ولایت فقیه بر ندارید و نماز و حجاب خود را حفظ کنید و در راه رضای خداوند قدم بردارید و خود را به آرامش برسانید. ظهور حضرت نزدیک است ان شاا... که زمینه ساز ظهور باشید.</p>\r\n\r\n<p>یادو خاطره ی همه شما در ذهن من هست و می ماند.</p>\r\n\r\n<p>براهل حرم، اگر جسارت بشود. این قافله، گر دوباره غارت بشود</p>\r\n\r\n<p>یک تن ز یزیدیان، نماند درشام بر لشکر حق ، اگر اشارت بشود</p>\r\n\r\n<p>خداحافظ ما خوشحال رفتیم</p>\r\n\r\n<p>روح اله صحرایی</p>\r\n', '1404-02-03 13:49'),
(5, 'شهید حاج قاسم میرحسینی', 'imgs/vasiatnameh_shohada/شهید_شاخص.jpg', '<p><strong>شهید حاج قاسم میرحسینی، جانشین و قائم مقام حاج قاسم سلیمانی در لشکر ۴۱ ثارالله..</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>والدین عزیزم، ایدکم ا...تعالی</p>\r\n\r\n<p>بار خدایا! به یگانگی&zwnj;ات و اینکه شریک و همتایی برایت نیست و معبود واقعی هستی شهادت می&zwnj;دهم.</p>\r\n\r\n<p>بار خدایا! به پیامبر خاتمت حضرت محمد(ص) که فرستاده و رسول توست شهادت می&zwnj;دهم و به اینکه حضرت علی(ع) پیشوا و امام اول شیعیان است و اینکه قیامت و محشر روز رستاخیز حق است شهادت می&zwnj;دهم.</p>\r\n\r\n<p>بار خدایا! به اینکه نظام جمهوری اسلامی به رهبری امام عزیز حق است و جنگ عراق علیه ایران به ما تحمیل شده و امروز فرزندان برومند ملت ما ایثارگرانه از تمامیت ارضی، اسلامی، عقیدتی و مکتبی خود دفاع می&zwnj;کنند شهادت می&zwnj;دهم.</p>\r\n\r\n<p>شاید مشیت حضرت داور بر این باشد که توفیق شهادت پیدا کنم. مع ذالک بد نیست این جملاتی که برگرفته از عقایدم می&zwnj;باشد بر روی کاغذ مکتوب کنم. به هر حال به خداوند و فضل و رحمتش چشم امید دوخته&zwnj;ام نه به بضاعت و توشه خویش. خدا گواه است توشه&zwnj;ای ندارم.</p>\r\n\r\n<p>مدتی در جنگ بودم که شاید بهار عمرم محسوب شود و در کنار وارسته&zwnj;ترین فرزندان این امت، قسمتی از عمرم را سپری کردم، که نعمت بسیار بزرگی بود. بسیجیانی که جز خدا را نمی&zwnj;دیدند و جز طریقت خدایی نمی&zwnj;پویند و آن خالصانی که با تکیه بر حقیقت توحید و معاد و عقاید و اخلاق، اعمال و حالات خود را از آلودگی&zwnj;ها شسته&zwnj;اند و جان و اعضا و جوارح خویش را به نور واقعیت تزیین کرده&zwnj;اند. آن کسانی که به نص کلام مولا علی(ع) دنیا را سه طلاقه کردند.</p>\r\n\r\n<p>پدر و مادرم! معذرت می&zwnj;خواهم که نتوانستم فرزند لایق و شایسته&zwnj;ای باشم و حق پدر فرزندی را ادا کنم. هرگز زحمات و مشقات شما را در مراحل مختلف زندگی فراموش نخواهم کرد. من در پیشگاه خداوند از شما تشکر و قدردانی می&zwnj;کنم.</p>\r\n\r\n<p>تکلیف حسینی اقتضا کرد که در جبهه حضور پیدا کنم. اگرچه از دست دادن جوان سخت است اما چون رضایت خدا بالاتر از هر چیزی است، شما هم باید رضا باشید به رضای خدا. فرزندتان امانتی بیش نبود، خدا امانتش را از شما گرفت، مع ذالک اندوه معنی پیدا نمی&zwnj;کند.</p>\r\n\r\n<p>من شرمنده&zwnj;ام وقتی به سنی رسید&zwnj;ام که خود را یافتم، در کنار شما نبودم تا قسمتی از خدمات بی&zwnj;شمار و زحمات زیادی که در جهت رشد و پرورش من متحمل شده&zwnj;اید را ادا کنم.از تشکر و عذرخواهی کردن از زحمت ارزنده&zwnj;تان زبانم عاجز است و قلم قاصر. از شما می&zwnj;خواهم برایم دعا کنید خدا گناهانم را ببخشد.</p>\r\n\r\n<p>چون ما ادامه&zwnj;دهندگان راه امام حسین(ع) هستیم، یزیدیان بر ما خورده&zwnj;گیری کردند و سپس قتل&zwnj;عاممان نمودند و همچون حیوانات درنده به ما حمله کردند. پیران و کودکان ما را کشتند. جوانان را تکه پاره و به زنان کهنسال و دختران خرد سال تجاوز کردند. یتیمان را سر بریدند. خانه&zwnj;ها را سوزاندند و شهرها را پس از غارت به ویرانه تبدیل کردند. یا اباعبدالله ... یاوران تو را دست بریدند، پا قطع کردند، سر جدا کردند، با مواد شیمیایی بدنشان را کباب کردند.</p>\r\n\r\n<p>چون از شما پدر و مادر مهربانم در کودکی آموخته&zwnj;ام وقتی داستان حماسه&zwnj;آفرینی&zwnj;های کربلای حسین(ع) را برایم تعریف می&zwnj;کردید تصمیم گرفتم با امام حسین بیعت کنم که: یا اباعبدالله ....انی سلم لمن سالمکم و حرب لمن حاربکم.</p>\r\n\r\n<p>پدرم! الگوی تو حضرت ابراهیم است. ابراهیم خود فرزندش را به قربانگاه عشق برد. تو خود مرا به جبهه روانه کردی. صبر داشته باش که خدا صابران را دوست دارد.</p>\r\n\r\n<p>مادرم! الگوی تو حضرت هاجر است، حضرت هاجر خودش چشمان فرزندش را برای قربانی در راه خدا سرمه کشید و تو مرا از زیر قرآن برای رفتن به جبهه عبور دادی؛ الحق که به تمام معنی مادر بودی. خداوند با کسانی است که در زندگی بردبار باشند و تو هاجروار مرا به جبهه روانه کردی.</p>\r\n\r\n<p>از برادران عزیزم که همیشه مرا هادی و راهنما بودند تشکر می&zwnj;کنم و عذر می&zwnj;خواهم که با بی&zwnj;ادبی و بد اخلاقی با آن&zwnj;ها حرف زدم و آن&zwnj;طور که شایسته مقام برادری بودند نتوانستم ادای تکلیف کنم. اگر توانستید برایم روزه بگیرید و نماز بخوانید. به برادرانم توصیه می&zwnj;کنم که در هر مجلس و محفلی از جنگ و انقلاب سخن بگویید. از مظلومیت ما در برابر ستمگران بگویید، از رهبری و ولایت فقیه سخن بگویید. یادتان نرود امام، ما را از اسفل&zwnj;السافلین به طرف اعلی علیین اوج داد.</p>\r\n\r\n<p>از خواهران بسیار عزیز و زحمت کشیده&zwnj;ام نهایت سپاسگذاری و تشکر را دارم و امیدوارم مرا عفو کنند و زحمات خود را بر من حلال کنند.</p>\r\n\r\n<p>خواهرم الگوی تو حضرت زینب است. حضرت زینب پیامبر کربلای خونین امام حسین(ع) بود. یادت باشد زینب با یک عده یتیم و زن و کودک اسیر دشمن شد اما از هدفش باز نماند و همچنان فریاد می&zwnj;زد. خونسرد باشید و مرا دشمن شاد نکنید. فرزندان شما باید انتقام شهدا را بگیرند. به فرزندانتان انتقام را بیاموزید.</p>\r\n\r\n<p>از پدر و مادر و خواهرانم تمنا می&zwnj;کنم در مراسم عزاداریم شربت و شیرینی پخش کنند و غمگین نباشند. به سر و صورت نزنند و جامه پاره نکنند. از حضرت زینب باید درس بگیرید، حضرت زینب با آن همه مشکلات و آن همه جنازه&zwnj;ای که در روز عاشورا شاهد بود، چنان متین و صبور بود که دشمنان را تکان می&zwnj;داد و سر افکنده می&zwnj;کرد.</p>\r\n\r\n<p>شما خودتان می&zwnj;شنوید در سر تا سر دنیا به مظلومین و مستضعفین رحم نمی&zwnj;کنند و در همه جا مسلمین و محرومین را سر می&zwnj;برند، بنابراین خودتان را آماده کنید که اگر در مرز سراغ آن&zwnj;ها نروید، خود سراغتان خواهند آمد.</p>\r\n\r\n<p>از عموها و مومنین که با آن&zwnj;ها رابطه داشته&zwnj;ام برایم طلب مغفرت کنید. اگر در حق هر کدامتان قصوری از جانب حقیر بوده است امیدوارم مرا عفو کنید.</p>\r\n\r\n<p>سخنی با برادران عزیزم، همرزم&zwnj;ها و همسنگرهای قدیمی، مخصوصا حاج قاسم سلیمانی، شاید مصلحت و مشیت حق بر این باشد که توفیق شهادت پیدا کنم و در این دارفانی همدیگر را وداع کنیم. لازم دیدم چند جمله به&zwnj;عنوان درد دل و ره&zwnj;آورد چندین ساله جنگ و درس&zwnj;هایی که حقیر گرفتم و بعضی&zwnj;ها را توفیق پیدا کردم به کار بندم و بعضی&zwnj;ها را دیر متوجه شدم، یادآور شوم.</p>\r\n\r\n<p>1-در جنگ هستید، هیچ برنامه&zwnj;ای از پیامدهای زندگی، شما را در امر جنگ و برنامه&zwnj;ریزی&zwnj;های آن سست و کم مقاومت نکند.</p>\r\n\r\n<p>2-علت عمده بریدن از جنگ و فشار ناشی از آن را باید در مسئل عقیدتی و روحی پیدا کرد، نه در کمبودهای آموزشی &ndash; کادری و تجهیزاتی، برای مثال اگر به قیامت، معاد، محشر و روز رستاخیز معتقد باشیم و باور کنیم همه هست و بر حق هم هست، هرگز از مرگ فرار نمی&zwnj;کنیم و هرگز دل به دنیا نخواهیم بست ولی چون روح ملکوتی نسبت به باورهای حضرت حق رشد کافی نکرده است و فنای درگاه عبودیت حق نگردیده است و قدرت کافی در برابر فشارهای مادی را ندارد همیشه دل&zwnj;زدگی، کدورت، نیش&zwnj;زبان، زخم&zwnj;زبان زدن و بعضا بریدن از جنگ را فراهم می&zwnj;آورد.</p>\r\n\r\n<p>۳-هیچ چیزی را به دل راه ندهید به حدی که الله شود و جای الله اصلی را بگیرد، که حضرت حق سریعا از آن دل رخت بر می&zwnj;بندد.</p>\r\n\r\n<p>4-راحتی&zwnj;های جنگ را سر همدیگر تقسیم کنید و مشکلات و سختی&zwnj;ها را نیز چنین کنید.</p>\r\n\r\n<p>۵-رده&zwnj;های پایین همیشه قوت قلب رده&zwnj;های بالا باشند و بالایی&zwnj;ها پدر و برادر بزرگ پایینی&zwnj;ها.</p>\r\n\r\n<p>6-در پیشگاه خداوند شهادت می&zwnj;دهم بسیجی&zwnj;ها اسوه&zwnj;ها و سنبل رزمندگان زمان انبیا و اولیا هستند و نباید با بودن چند نفر غیر بسیجی در لباس مقدس آنان همه را به یک چشم دید.</p>\r\n\r\n<p>7-امت حزب&zwnj;الله، خانواده&zwnj;های معظم شهدا، مفقودالاثرها و اسرا و جانبازان و سایر اقشار که ذیحق انقلاب اسلامی می&zwnj;باشند، به حق، همراه امام و مقاوم با امام حرکت کردند و باید برادران جنگ به&zwnj;عنوان پیشتازان این حرکت، گرمی و نشاط و حرارت و سرعت بیشتر از بقیه داشته باشند.</p>\r\n\r\n<p>8-من حقی بر گردن هیچ کدام از شما ندارم و انتظار دارم مرا عفو کنید و از سایر برادران آشنا برایم حلالیت و عفو طلب کنید و من اگر حقی داشته باشم همه را می&zwnj;بخشم.</p>\r\n\r\n<p>در پایان صحبتم، سخنی با مسئولین رده بالا از لشگر مخصوصا برادر شمخانی دارم که بنابه صحبت حضرت امام، منتظر نباشید تا قدرت بگیرید بلکه حرکت کنید تا قدرت بگیرید. انتظار می&zwnj;رود با توجه به نیاز استان سیستان و بلوچستان و ارزش استراتژیکی آن، با بودن کادر موجود در لشگر سرمایه&zwnj;گذاری شود و آنجا در قالب یگان مستقل ولی تحت امر لشگر ثارالله یا هر یگانی صلاح دیدند در جنگ خدمت کند و در راستای ارتش بیست میلیونی گامی بلند برداشته شود.</p>\r\n\r\n<p>همسرم شرمنده&zwnj;ام که با سیاه کردن کاغذی سفید قلب صاف و پاکت را تسلی می&zwnj;دهم. شاید لحظه موعود فرا رسد و از همدیگر در این دنیا جدا شویم. مواردی را که ذکر می&zwnj;کنم خوب به خاطر بسپار.</p>\r\n\r\n<p>تا زنده بودم نتوانستم حقی را که به گردنم داشتی آن طور که شایسته است ادا کنم و همچون سایرین زندگی عادی و معمولی و پر از عاطفه را کنار هم سپری کنیم و شاید هم این نوع زندگی میراث انبیاء الهی و اولیای عظام و کرام باشد که برایمان ارث مانده است. مع ذالک میراث گران&zwnj;بهایی است که باید قدر آن را دانست.</p>\r\n\r\n<p>همسرم! اینک که سفر نهایی در پیش است همچون گذشته تو را به خدای متعال می&zwnj;سپارم زیرا او بهترین نگه&zwnj;دارنده و پاسدار واقعی است.</p>\r\n\r\n<p>همسرم! در همه امور بر خدا توکل کن؛ از تنهایی&zwnj;های دنیایی به او پناه ببر؛ در نامیدی&zwnj;ها از خداوند امید جوی؛ در مصائب و بلاها و مشکلات زندگی، که گردش معمول دنیاست، از صبر توشه گیر و در طریقت حضرت حق تلاشی مستمر داشته باش. به احکام خوب عمل کن. همه وقت به یاد معبود اصلی باش. همیشه منتظر باش دست عنایت غیبی خداوند بر تو سایه&zwnj;افکن شود. دنیای فانی به هیچ کس وفایی نداشته است و نهایت کمال و غایت بلندی آن فناست. فنا در خدا و رسیدن به لقای پروردگار.</p>\r\n\r\n<p>مرگ همه را در کام خود می&zwnj;بلعد و چون مرگ حتمی است، معقول است مرگ، مرگ حسینی باشد و زندگی در جهان هستی زمینه سازندگی و حیاط اخروی باشد و بهتر است با مرگ شرافتمندانه در پیشگاه انبیاء و اولیا و شهدا سر افکنده و خجل نباشیم.</p>\r\n\r\n<p>همسرم! وقتی خبر شهادتم را به تو دادند استوار و ثابت قدم، زینب&zwnj;گونه باش و همچون او به دور از جزع و فزع پیام&zwnj;رسان خون شهیدان باش. شاید بعد از شهادتم احساس تنهایی و آوارگی کنی و دنیا را بر خود تیره و تار تجسم کنی، در آن موقع لازم است بیشتر نماز بخوانی و اوقات فراغت را با قرآن و خود را به کارهای خانه مشغول کن. در رفت و آمدهای زندگی و حفظ صله&zwnj;رحم مواظب باش به دینت لطمه و آسیب نرسد بلکه بر ایمانت افزوده گردد. و بدان کسانی که از صابران جمهوری اسلامی و گردانندگان واقعی آن انتقاد کنند، با هر لحن و زبانی که باشد، مطمئن باش که اینان دشمن واقعی و خطرناک اسلام و انقلاب اسلامی و رهبری و امام عزیز می&zwnj;باشند و یا این&zwnj;که ممکن است دوست کم عقل و ناآگاه باشند. در هر صورت از آن&zwnj;ها برهذر باش و در دین و عاقبت زندگی خود خوف داشته باش.</p>\r\n\r\n<p>همسرم! وصیت می&zwnj;کنم اگر فرزندم پسر بود اسمش را حسین بگذارید زیرا مسئولیت حسینی دارد و باید بار حسینیان را بر دوش کشد، حسین&zwnj;وار زندگی کند و حسین&zwnj;وار بمیرد و اگر دختر بود اسمش را زینب بگذارید، زینب&zwnj;گونه فریاد بزند و زینب&zwnj;گونه بمیرد. و از حضرت زینب و مظلومیت شهدای کربلای امام حسین(علیه السلام) و ایران برایش لالایی بگو، برایش بگو حضرت زینب(س) خود شهدای کربلا را دفن &zwnj;کرد، یتیمان و کودکان را خود سرپرستی &zwnj;کرد و خود شعار پیروزی خون بر شمشیر را فریاد زد. بگو پیامبر کربلای خونین و عاشورای سرخ&zwnj;گون امام حسین(ع) حضرت زینب(س) بود که بعد از شهدای کربلای امام حسین(ع) بنای کاخ&zwnj;های ظلم و جور یزیدیان را فروریخت.</p>\r\n\r\n<p>مسائل ذیل را توصیه می&zwnj;کنم:</p>\r\n\r\n<p>- از همه برایم طلب عفو کن و بالاخص اقوام نزدیک که با آن&zwnj;ها خیلی رفت و آمد داشته&zwnj;ایم.</p>\r\n\r\n<p>- نماز و روزه قضا قریب به ۵ماه و شاید بیشتر باشد.</p>\r\n\r\n<p>- مخارج مراسم را از اموال شخصی&zwnj;ام برداشت کنید.</p>\r\n\r\n<p>- در قبرستان جزینک دفنم کنید و بر روی سنگ قبرم چیز اضافی غیر از اسم و عرف معمولی چیزی ننویسید.</p>\r\n\r\n<p>- تشریفات ساده باشد از کسی تسلیت قبول نکنید و با روحیه باشید.</p>\r\n\r\n<p>- فقط برایم چهلم بگیرید.</p>\r\n\r\n<p>- وسایل نظامی، اگر خانه باشد تحویل سپاه دهید تا برادرانم در جنگ به کار ببرند.</p>\r\n\r\n<p>- سکه&zwnj;ها را هر طور سلاح می&zwnj;دانی خرج کن (سکه&zwnj;های عیدی)</p>\r\n\r\n<p>- مبلغ دوازده هزار تومان به لشگر و سی هزار تومان به سپاه و کمتر از پنجاه هزار تومان به صندوق قرض&zwnj;الحسنه بقیه&zwnj;الله کرمان بدهکارم.</p>\r\n\r\n<p>- کتبم از آن برادرانم است. هر طور صلاح می&zwnj;دانند استفاده کنند.</p>\r\n', '1404-02-03 13:57'),
(6, 'شهید مصطفی صدرزاده', 'imgs/vasiatnameh_shohada/1715251142YRN94WG047721.jpg', '<p><strong>بِسمِ رَبّ الوفا و رب الشّهداء وَ الصّدقین</strong></p>\r\n\r\n<p>خدایا بر محمد و آل محمد درود فرست&zwnj;،&zwnj; سپاس خدایی را که بر سر ما منت نهاد و از میان این همه مخلوق ما را انسان خلق کرد.</p>\r\n\r\n<p>شکر خدایی را که از میان این&zwnj;همه انسان ما را خاکی مقدس به نام ایران قرار داد.</p>\r\n\r\n<p>و شکر خدایی را که به بنده پدر و مادر و همسر صالح عطا کرد.</p>\r\n\r\n<p>و شکر بی&zwnj;پایان خدایی را که محبت شهدا و امام شهدا را در دلم انداخت و به بنده توفیق داد تا در بسیج خادم باشم. خدایا از تو ممنونم بی&zwnj;اندازه که در دل ما محبت سید علی&zwnj;خامنه&zwnj;ای را انداختی تا بیاموزد درس ایستادگی را درس اینکه یزید&zwnj;های دوران را بشناسیم و جلوی آنها سر خم نکنیم. از تمام دوستان و آشنایان در ابتدای وصیت&zwnj;نامه خویش تقاضا دارم به فرامین مقام معظم رهبری گوش&zwnj; دهند تا گمراه نشوند. زیرا ایشان بهترین دوست شناس و دشمن شناس است. از پدر و خانواده عزیزم تقاضا دارم برای بنده بی&zwnj;تابی و ناراحتی بیش&zwnj; از حد نکنند و اشک&zwnj;ها و گریه&zwnj;های خود را نثار اباعبدالله و فرزندان آن بزرگوار کنند.</p>\r\n\r\n<p>پدر و مادر و همسرم و دخترم از شما تقاضا می&zwnj;کنم بنده&zwnj;رو ببخشید و از خدا بخواهید بنده&zwnj;رو ببخشد چقدر در حق پدر و مادر کوتاهی کردم چقدر شما را به دردسر انداختم فقط خدا شاهد تلاش شما بود که در زمان جنگ باید سختی و مشقت از من نگه&zwnj;داری کردید و بعد از جنگ هم برای درس&zwnj;خواندن من چقدر سختی کشیدید. فقط خدا می&zwnj;داند که چقدر نگران کرده&zwnj;ام اذیت کرده&zwnj;ام و شما تحمل کردید زیرا تلاش&zwnj; می&zwnj;کردید تا فرزندتان عاقبت&zwnj; به خیر شود از شما ممنونم که همیشه انتخاب را به عهده خودم گذاشتید. حتی وقتی در نوجوانی می&zwnj;خواستم به نجف برای تحصیل بروم مخالفت نکرده و از اینکه همیشه به نظر من احترام گذاشتید ممنونم حالا هم از شما خواهش می&zwnj;کنم یکبار دیگر و برای آخرین بار به نظرم احترام بگذارید و از هیچ&zwnj;کس و از هیچ نهادی دلخور نباشید مبارزه با دشمنان خود آرزوی بنده بود و فقط خدا می&zwnj;داند برای این آرزو چقدر ضجه زدم و التماس کردم ممکن است بعضی&zwnj;ها به شما طعنه بزنند اما اهمیت ندهید بنده به راهی که رفتم یقین داشتم.</p>\r\n\r\n<p>از همسر عزیزم می&zwnj;خواهم که بنده را ببخشد زیرا که همسر خوبی برای او نبودم. به همسر عزیزم می&zwnj;گویم می&zwnj;دانم که بعد از بنده دخترم یتیم می&zwnj;شود و شما اذیت می&zwnj;شوید اما یادت باشد که رسول خدا فرموده: هرکس که یتیم شود خدا سرپرست اوست ایمان داشته باش که خدا همیشه با توست. آرزو دارم که دخترم فاطمه،&zwnj;فاطمی تربیت شود یعنی مدافع سرسخت ولایت، از دوستان،&zwnj; آشنایان و فامیل و هرکس که حقی گردن ما دارد تقاضا می&zwnj;کنم بنده حقیر با ببخشد زیرا می&zwnj;دانم که اخلاق و رفتار من آنقدر خوب نبود که توفیق شهادت داشته باشم و این شما حتی که نصیب ما شد لطف و کرم و هدیه خدا بوده و مردم عزیز ایران یادمان باشد که به خاطر وجب به وجب این سرزمین و دین اسلام چقدر خون دادیم چقدر بچه&zwnj;های ما یتیم شدند،&zwnj; زن&zwnj;ها بیوه، مادرها مجنون، پدرها گریان فقط و فقط برای خدا بود. در این ماه مبارک رمضان دل ما شکست،&zwnj; دل امام زمان بیشتر و بیشتر که در مملکت شهدا حرمت ماه خدا توسط بعضی&zwnj;ها نگه&zwnj;داشته نشد و برادارن و خواهران من ماهواره و فرهنگ کثیف غرب مقصدی به جز آتش دوزخ ندارد. از ما گفتن ما که رفتیم...</p>\r\n\r\n<p>آن کس که تو را شناخت جان را چه کند</p>\r\n\r\n<p>فرزند و عیال و خانمان را چه کند</p>\r\n\r\n<p>دیوانه کنی هر دو جهانش بخشی</p>\r\n\r\n<p>دیوانه تو هر دو جهان را چه کند</p>\r\n\r\n<p>بی&zwnj;بی زینب آن زمانی که شما در شام&zwnj; غریب بودید گذشت دیگر به احدی اجازه نمی&zwnj;دهیم به شما و به سلاله حسین بی&zwnj;احترامی کند. دیگر دوران مظلومیت شیعه تمام شده. بی&zwnj;بی&zwnj;جان انی سلم لمن سالمکم و حرب لمن حاربکم بی&zwnj;بی عزیزم مرا قاسم خطاب کن مرا قاسم خطاب کن روی خون ناقابل من هم حساب کن</p>\r\n\r\n<p>و من&zwnj;الله توفیق مصطفی صدر زاده</p>\r\n', '1404-02-05 10:23'),
(7, 'شهید محسن حججی', 'imgs/vasiatnameh_shohada/images_1.jpeg', '<p><strong>بِسمِ رَبّ الوفا و رب الشّهداء وَ الصّدقین</strong></p>\r\n\r\n<p><strong>قسمت اول وصیت نامه&nbsp;شهید محسن حججى</strong></p>\r\n\r\n<p>برای بانوی صبر</p>\r\n\r\n<p>السلام ای بانوی سلطان عشق</p>\r\n\r\n<p>السلام ای بانوی صبر دمشق</p>\r\n\r\n<p>زیبنبِ دنیا و عقبیِ علی</p>\r\n\r\n<p>شرح مدح لافتی الا علی</p>\r\n\r\n<p>در مسیر شام غوغا کرده ایی</p>\r\n\r\n<p>شهر را آشوب برپا کرده ایی</p>\r\n\r\n<p>خطبه خواندی از غریبی حسین</p>\r\n\r\n<p>زنده کردی کربلا در عالمیین</p>\r\n\r\n<p>گر نبودی کربلایی هم نبود</p>\r\n\r\n<p>گریه و شور و نوایی هم نبود</p>\r\n\r\n<p>رنج هایی ست فراوان دیده ایی</p>\r\n\r\n<p>خیمه ها، غارت، سواران دیده ایی</p>\r\n\r\n<p>دیده بودی، حلق و چشم و حرمله</p>\r\n\r\n<p>گریه کردی پا به پای قافله</p>\r\n\r\n<p><strong>بسم الله النور...</strong></p>\r\n\r\n<p>صَلی الله علیک یا اُماه یا فاطمه الزهرا&quot;سلام علیک&quot;</p>\r\n\r\n<p>وَلاتَحسَبن الذینَ قُتلوا فی سَبیل الله اَمواتا، بَل احیاء عند رَبِهم یُرَزقون</p>\r\n\r\n<p>هرگز نمیمیرد آنکه دلش زنده شد به عشق ثبت است بر جدیده عالم دوام ما...</p>\r\n\r\n<p>چند ساعتی بیشتر به رفتن نمانده است، هرچه به زمان رفتن نزدیک تر می شوم قلبم بی تاب تر می شود...نمی دانم چه بنویسم و چگونه حس و حالم را بیان کنم...نمی دانم چگونه خوشحالی ام را بیان کنم و چگونه و با چه زبانی شکر خدای منان را به جای بیاورم...به حسب وظیفه چند خطی را به عنوان وصیت با زبان قلم می نویسم...نمیدانم چه شد که سرنوشت مرا به این راه پر عشق رساند... نمی دانم چه چیزهایی عامل آن شد...بدون شک شیر حلال مادرم، لقمه حلال پدرم و انتخاب همسرم و خیلی چیزهای دیگر در آن اثر داشته است...</p>\r\n\r\n<p><strong>قسمت دوم وصیت نامه&nbsp;شهید محسن حججى</strong></p>\r\n\r\n<p>عمریست شب و روزم را به عشق شهادت گذرانده ام... و همیشه اعتقادم این بوده و هست که با شهادت به بالاترین درجه ی بندگی میرسم...خیلی تلاش کردم که خودم را به این مقام برسانم اما نمی دانم که چقدر توانسته ام موفق باشم...چشم امیدم فقط به کرم خدا و اهل بیت است و بس امید دارم این رو سیاه پرگناه را هم قبول کنند و به این بنده ی بدِ پرخطا نظری از سر رحمت بنمایند...</p>\r\n\r\n<p>که اگر این چنین شد؛ الحمدالله رب العالمین...اگر روزی خبر شهادت این بنده حقیر سرا پا تقصیر را شنیدید؛ علت آن را جز کریمی و رحیمی خدا ندانید...اوست که رو سیاهی چون مرا هم می بخشد و مرا یاری می کند...</p>\r\n\r\n<p>همسر عزیزم زهرا جانم</p>\r\n\r\n<p>اگر روزی خبر شهادتم را شنیدی بدان به آرزویم که هدف اصلی ام از ازدواج با شما بود رسیدم و به خود افتخار کن که شوهرت فدای حضرت زینب شد...مبادا بی تابی کنی، مبادا شیون کنی، صبور باش و هر آن خودت را در محضر حضرت زینب بدان... حضرت زینب بیش از تو مصیبت دید.</p>\r\n\r\n<p>پدر عزیزم</p>\r\n\r\n<p>همیشه و در همه حال الگوى زندگی و مردانگی ام تو بوده و هستی، اگر روزی خبر شهادتم را دیدی، زمانی را در مقابل خود فرض کن که حسین بن علی در کنار جگر گوشه اش علی اکبر حاضر شد...داغ تو بیشتر از داغ اباعبدالله نیست... پس صبور باش پدرم، می دانم سخت است اما می شود...</p>\r\n\r\n<p>مادر عزیزم</p>\r\n\r\n<p>ام البنین علیهاالسلام 4 جوان خود را فدای حسین و زینب کرد و خم به ابرو نیاورد.حتی زمانی که خبر شهادت پسرانش را به آن دادند باز از حسین سراغ گرفت؛ پس اگر روزی خبر شهادتم را شنیدی، همچون ام البنین صبورانه و با افتخار فریاد بزن که مرا فدای حسین و حضرت زینب کرده ای و مبادا با بی تابی خود دل دشمن را شاد کنید...</p>\r\n\r\n<p><strong>قسمت سوم وصیت نامه&nbsp;شهیدمحسن حججى</strong></p>\r\n\r\n<p>برادر عزیزم</p>\r\n\r\n<p>اگر روزی مرا در لباس شهادت دیدی آن لحظه ایی را به یاد بیاور که اباعبدالله بر بالین عباس ابن علی حاضر شد و داغ برادر کمرش را خم کرد...مبادا ناسپاسی کنی، مبادا به هدیه ایی که تقدیم اسلام کرده اید شک بیاورید...</p>\r\n\r\n<p>خواهران خوبم</p>\r\n\r\n<p>لحظه ی وداع با شما و مادرم و پدرم مرا به یاد آن لحظه ایی انداخت که اهل حرم حضرت علی اکبر را راهی میدان جنگ می کردند؛ پس اگر من هم رو سفید شدم غم و غصه و اشک و ناله خود را فدای علی اکبر کنید و مبادا داغ خود را از داغ دل اهل حرم بیشتر بدانید...</p>\r\n\r\n<p>پسر عزیزم، علی جان...</p>\r\n\r\n<p>ببخشید اگر قد کشیدنت را ندیدم و مرد شدنت را نظاره نکردم... سعی کن راه مرا ادامه بدهی... سعی کن کاری کنی که سرانجام آن به شهادت ختم شود...</p>\r\n\r\n<p>پدر و مادر همسر عزیزم...</p>\r\n\r\n<p>همیشه شما را همچون پدر و مادر واقعی خودم می دانستم و خوشحال ام که سرنوشتم با حضور در خانواده شما رقم خورد...</p>\r\n\r\n<p>به شما هم جز صبر و تحمل چیز دیگری سفارش نمی کنم، همیشه یاد داشته باشید علی اکبر حسین هم تازه داماد کربلا بود...</p>\r\n\r\n<p>از همه میخوام این رو سیاه را حلال کنید، اگر حقی از کسی ضایع کردم، اگر غیبتی پشت سر کسی کردم، اگر دلی را رنجاندم، اگر گناهی از من سر زد؛ حلالم کنید...اگر شهید شدم تا جایی که اجازه داشته باشم؛ شفیعتان خواهم بود.</p>\r\n\r\n<p><strong>قسمت چهارم وصیت نامه&nbsp;شهیدمحسن حججی</strong></p>\r\n\r\n<p>از ولایت فقیه غافل نشوید و بدانید من به یقین رسیدم که امام خامنه&zwnj;ای نائب بر حق امام زمان است.از همه ی خواهران عزیزم و از همه ی زنان امت رسول الله می خواهم روز به روز حجاب خود را تقویت کنید، مبادا تار مویی از شما نظر نامحرمی را به خود جلب کند؛ مبادا رنگ و لعابی بر صورتتان باعث جلب توجه شود؛ مبادا چادر را کنار بگذارید...</p>\r\n\r\n<p>همیشه الگوی خود را حضرت زهرا&nbsp; و زنان اهل بیت قرار دهید؛ همیشه این بیت شعر را به یاد بیاورید:</p>\r\n\r\n<p>آن زمانی که حضرت رقیه سلام الله خطاب به پدرش فرمودند:</p>\r\n\r\n<p>غصه ی حجاب من را نخوری بابا جان</p>\r\n\r\n<p>چادرم سوخته اما به سرم هست هنوز...</p>\r\n\r\n<p>از همه ی مردان امت رسول الله می خواهم فریب فرهنگ و مدهای غربی را نخورید؛ همواره علی ابن ابی طالب امیرالمومنین را الگو و پیشوای خود قرار دهید و از شهداء درس بگیرید...خودتان را برای ظهور امام زمان روحی لک الفدا و جنگ با کفار به خصوص اسرائیل آماده کنید که آن روز خیلی نزدیک است.همیشه برای خدا بنده باشید که اگر این چنین شد بدانید عاقبت همه ی شما به خیر ختم می شود...</p>\r\n\r\n<p>مقداری حق الناس به گردن دارم که عاجزانه می خواهم برایم ادا کنید...</p>\r\n\r\n<p>- یک میلیون تومان به مادر بزرگ پدری بدهکارم</p>\r\n\r\n<p>- مقداری بدهی به برادر محسن همتی ها بابت محصولات فرهنگی و کارهای دیگر بدهکارم</p>\r\n\r\n<p>- 32 هزارتومان به اضافه مقداری سربند به پایگاه شهدای بنیاد امیرآباد بدهکارم</p>\r\n\r\n<p>- اگر برایتان مقدور بود به مقدار یک ماه نماز و روزه برایم ادا کنید که اگر خدایی ناکرده گهگاهی از روی خطا نمازی قضا کردم و یا روزه ایی از دست دادم جبران شود...</p>\r\n\r\n<p>الهم عجل لولیک الفرج&nbsp;اللَّهُمَّ اجْعَلْنِی مِنْ أَنْصَارِهِ وَ أَعْوَانِهِ وَ الذَّابِّینَ عَنْهُ وَ الْمُسَارِعِینَ إِلَیْهِ فِی قَضَاءِ حَوَائِجِهِ وَ الْمُحَامِینَ عَنْهُ وَ السَّابِقِینَ إِلَى إِرَادَتِهِ وَ الْمُسْتَشْهَدِینَ بَیْنَ یَدَیه.</p>\r\n', '1404-02-06 00:47');
INSERT INTO `panel_app_vasiatnamehshohada` (`id`, `vasiatnameh_shohada_name`, `vasiatnameh_shohada_img`, `vasiatnameh_shohada_text`, `date_created`) VALUES
(8, 'شهید ابراهیم هادی', 'imgs/vasiatnameh_shohada/2381491_562.jpg', '<p><strong>بسم رب الشهداء و الصدیقین</strong></p>\r\n\r\n<p>اگر چه بیش از هر کس، خود را محتاج وصیت و پند و اندرز می دانم، پیش از آغاز سخن از خداوند منان تمنّا می کنم که قدرتی به بیان من بدهد که بتوانم از زبان یک شهید، دست به قلم ببرم چرا که جملات من پیدا شد و مورد عفو رحمت الهی قرار گرفتم و توفیق و سعادت شهادت را پیدا کردم، بعنوان پرافتخارآفرین وصیای شهید خوانده می شود.</p>\r\n\r\n<p>خدایا تو را گواه می گیرم که از شروع انقلاب تا به حال در طول این مدت هر چه کردم برای رضای تو بوده و سعی داشتم همیشه خود را در مقابل آزمایش ها، مورد آزمایش و آموزش قرار دهم. امیدوارم در راه اسلام عزیز و پیروزی مستضعفین بر متکبرین، این جان ناقابل را بپذیری.</p>\r\n\r\n<p>خدایا با این که از شکستگی های متعدد استخوان هایم رنج می برم، ولی اهمیتی نمی دادم؛ به این خاطر که من در این مدت نسبت به آن هایی که خالصانه در این راه گام نهاده اند، نشانه هایی از لطف و رحمت تو دیده ام.</p>\r\n\r\n<p>خدایا، ای معبودم و معشوقم و همه کس و کارم، نمی دانم چگونه در برابر عظمت تو ستایش کنم ولی همین قدر می دانم که هر کس تو را شناخت، عاشقت شد و هر کس عاشقت شد، دست از همه چیز شسته و به سوی تو می شتابد و به خوبی این را در خود احساس کردم و می کنم.</p>\r\n\r\n<p>خدایا چنان عشق به انقلاب اسلامی و رهبر کبیر انقلاب در وجودم شعله ور است که اگر تکه تکه شوم و یا زیر سخت ترین شکنجه ها قرار گیرم، او را تنها نخواهم گذاشت. بعنوان یک فردی از آحاد ملت مسلمان به تمامی ملت خصوصاً مسئولین امر تذکر می دهم که همیشه در جهت اسلام و قرآن باشید و هیچ مسأله و روشی شما را از هدف و جهتی که دارید، منحرف ننماید.</p>\r\n\r\n<p>دیگر اینکه در کارهایتان سعی کنید نیت خود را خالص نموده و از هر شرک و ریا، حسادت و بغض اعمالتان را پاک نمایید تا هم اجر خود را ببرید و هم مسئولیت خود را آنچنان که خداوند، اسلام و امام می خواهند، انجام داده باشید هرگز این را فراموش نکنید تا خود را نسازیم و تغییر ندهیم، جامعه ساخته نمی شود.</p>\r\n\r\n<p>والسلام و علیکم و رحمه الله و برکاته</p>\r\n\r\n<p>ابراهیم هادی پور</p>\r\n', '1404-02-06 00:58'),
(9, 'شهید مهدی باکری', 'imgs/vasiatnameh_shohada/300px-M_bakeri.jpg', '<p>وصیت نامه بنده گنهکار مهدی باکری</p>\r\n\r\n<p>یا الله یا محمد (ص) یا علی(ع) یا فاطمه زهرا یا حسن(ع) یا حسین(ع) یا علی(ع) یا محمد(ع) یا جعفر(ع) یا موسی(ع) یا علی(ع) یا محمد(ع) یا علی(ع) یا حسن(ع) یا حجه (عج) یا روح الله و شما ای پیروان صادق یا شهیدان</p>\r\n\r\n<p>خدایا چگونه وصیتنامه بنویسم در حالی که سراپا گناه و معصیت و نافرمانی ام. گرچه از رحمت و بخشش تو ناامید نیستم ولی ترسم از این است که نیامرزیده از دنیا بروم. می ترسم رفتنم خالص نباشد و پذیرفته درگاهت نشوم. یا رب العفو، خدایا نمیرم در حالی از ما راضی نباشی. ای وای که سیه روز خواهم بود.خدایا چقدر دوست داشتنی و پرستیدنی هستی! هیهات که نفهمیدم. یا اباعبدالله شفاعت! آه چقدر لذتبخش است انسان آماده باشد برای دیدار ربش، و چه کنم که تهیدستم،خدایا تو قبولم کن.</p>\r\n\r\n<p>سلام بر روح خدا، نجات دهنده ما از عصر حاضر، عصر ظلم وستم، عصر کفر و الحاد، عصر مظلومیت اسلام وپیروان واقعی اش. عزیزانم شبانه روز باید شکرگزار خدا باشیم که سرباز راستین صادق این نعمت شویم و باید خطر وسوسه های درونی و دنیافریبی را شناخته و بر حذر باشیم که صدق نیت و خلوص در عمل، تنها چاره ساز است.</p>\r\n\r\n<p>ای عاشقان اباعبدالله، بایستی شهادت را در آغوش گرفت، گونه ها بایستی از شوقش سرخ شود و ضربان قلب تندتر بزند. بایستی محتوای فرامین امام را درک و عمل کنیم تا بلکه قدری از تکلیف خود را در شکر گزاری بجا آورده باشیم.</p>\r\n\r\n<p><strong>&nbsp;وصیت به مادرم و خواهران و برادرانم و اهل فامیل</strong></p>\r\n\r\n<p>بدانید اسلام تنها راه نجات و سعادت ماست، همیشه به یاد خدا باشید و فرامین خدا را عمل کنید، پشتیبان و از ته قلب مقلد امام باشید، اهمیّت زیاد به دعاها و مجالس یاد اباعبدالله و شهدا بدهید که راه سعادت و توشه آخرت است. همواره تربیت حسینی و زینبی بیابید و رسالت آنها را رسالت خود بدانید و فرزندان خود را نیز همانگونه تربیت کنید تا سربازانی با ایمان و عاشق شهادت و علمدارانی صالح وارث حضرت ابوالفضل برای اسلام ببار آیند. از همه کسانی که از من رنجیده اند و حقی بر گردن من دارند طلب بخشش دارم و امید دارم خداوند مرا با گناهان بسیار بیامرزد.</p>\r\n\r\n<p><big><span style=\"color:#e74c3c\"><strong>خدایا مرا پاکیزه بپذیر...</strong></span></big></p>\r\n', '1404-02-06 01:10'),
(10, 'شهید احمد کاظمی', 'imgs/vasiatnameh_shohada/profile-20190504124827.jpeg', '<p>بسم الله الرحمن الرحيم</p>\r\n\r\n<p>الله اكبر</p>\r\n\r\n<p>اشهد ان لا اله الا الله اشهد ان محمد رسول الله اشهد ان علياً ولي الله</p>\r\n\r\n<p>اعوذ بالله من الشيطان رجيم صدق الله العلي العظيم السلام عليكم و رحمه الله و بركاته</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>خداوندا فقط مي خواهم شهيد شوم</p>\r\n\r\n<p>شهيد در راه تو، خدايا مرا بپذير و در جمع شهدا قرار بده. خداوندا روزي شهادت مي خواهم كه از همه چيز خبري هست الا شهادت، ولي خداوندا تو صاحب همه چيز و همه كس هستي و قادر توانايي، اي خداوند كريم و رحيم و بخشنده، تو كرمي كن، لطفي بفرما، مرا شهيد راه خودت قرار ده. با تمام وجود درك كردم عشق واقعي تويي و عشق شهادت بهترين راه براي دست يافتن به اين عشق.</p>\r\n\r\n<p>نمي دانم چه بايد كرد، فقط مي دانم زندگي در اين دنيا بسيار سخت مي باشد. واقعاً جايي براي خودم نمي يابم.</p>\r\n\r\n<p>هر موقع آماده مي شوم چند كلمه اي بنويسم، آنقدر حرف دارم كه نمي دانم كدام را بنويسم، از درد دنيا، از دوري شهدا، از سختي زندگي دنيايي، از درد دست خالي بودن براي فرداي آن دنيا، هزاران هزار حرف ديگر، كه در يك كلام، اگر نبود اميد به حضرت حق، واقعاً چه بايد مي كرديم. اگر سخت است، خدا را داريم اگر در سپاه هستيم. خدا را داريم اگر درد دوري از شهداي عزيز را داريم، خدا را داريم. اي خداي شهدا، اي خداي حسين(ع)، اي خداي فاطمة زهرا(س)، بندگي خود را عطا بفرما و در راه خودت شهيدم كن، اي خدا يا رب العالمين.</p>\r\n\r\n<p>راستي چه بگويم، سينه ام از دوريِ دوستانِ سفركرده از دردِ ديگر تحمل ندارد. خداوندا تو كمك كن. چه كنم فقط و فقط به اميد و لطف حضرت تو اميدوار هستم.</p>\r\n\r\n<p>خداوندا خود مي دانم بد بودم و چه كردم كه از كاروان دوستان شهيدم عقب مانده ام و دوران سخت وسخت را بايد تحمل كنم. اي خداي كريم، اي خداي عزيز و اي رحيم و كريم، تو كمك كن به جمع دوستان شهيدم بپيوندم.</p>\r\n\r\n<p>چه بدم و اي خدا تو رحم كن و كمك كن. بدي مرا مي بيني، دوست دارم بنده باشم، بندگي ام را ببين. اي خداي بزرگ، رب من، اگر بدم و اگر خطا مي كنم، از روي سركشي نيست، بلكه از روي ناداني مي باشد. خداوندا من بسيار در سختي هستم، چون هر چه فكر مي كنم، مي بينم چه چيز خوب و چه رحمت بزرگي از دست دادم. ولي خداي كريم، باز اميد به لطف و بزرگي تو دارم. خداوندا تو توانايي. اي حضرت حق، خودت دستم را بگير، نجاتم بده از دوري از شهدا، كارِ خوب نكردن، بندة خوب نبودن،... ديگر...</p>\r\n\r\n<p>حضرت حق، اميد تو اگر نبود پس چه؟ آيا من هم در آن صف بودم. واي چه روزهاي خوشي بود وقتي به عكس نگاه مي كنم. از دردِ سختي كه تمام وجودم را مي گيرد ديگر تحمل ديدن را ندارم. دوران لطف بي منتهاي حضرت حق، دوران جهاد، دوران عشق، دوران رسيدن آسان به حضرت حق، واي من بودم نفهميدم، واي من هستم كه بايد سختي دوران را طي كنم. الله اكبر خداوندا خودت كمك كن خداوندا تو را به خون شهداي عزيز و همة بندگان خوبت قسم مي دهم، شهادت را در همين دوران نصيب بفرماييد و توفيق ام بده هر چه زود تر به دوستان شهيدم برسم،</p>\r\n\r\n<p>انشاء الله تعالي.</p>\r\n', '1404-02-06 01:16'),
(11, 'سردار شهید حاج قاسم سلیمانی', 'imgs/vasiatnameh_shohada/5321237.jpg', '<p>بسم الله الرحمن الرحیم</p>\r\n\r\n<p><strong>شهادت می&zwnj;دهم به اصول دین</strong></p>\r\n\r\n<p>اشهد أن لا اله الا الله و اشهد أنّ محمداً رسول الله و اشهد أنّ امیرالمؤمنین علی&zwnj;بن ابی&zwnj;طالب و اولاده المعصومین اثنی&zwnj;عشر ائمّتنا و معصومیننا حجج الله.</p>\r\n\r\n<p>شهادت می&zwnj;دهم که قیامت حق است، قرآن حق است، بهشت و جهنّم حق است، سؤال و جواب حق است، معاد، عدل، امامت، نبوت حق است.</p>\r\n\r\n<p><strong>خدایا! تو را سپاس می&zwnj;گویم به&zwnj; خاطر نعمتهایت.</strong></p>\r\n\r\n<p>خداوندا! تو را سپاس که مرا صلب به صلب، قرن به قرن، از صلبی به صلبی منتقل کردی و در زمانی اجازه ظهور و وجود دادی که امکان درک یکی از برجسته&zwnj;ترین اولیائت را که قرین و قریب معصومین است، عبد صالحت خمینی کبیر را درک کنم و سرباز رکاب او شوم. اگر توفیق صحابه رسول اعظمت محمد مصطفی را نداشتم و اگر بی&zwnj;بهره بودم از دوره مظلومیت علی&zwnj;بن ابی&zwnj;طالب و فرزندان معصوم و مظلومش، مرا در همان راهی قرار دادی که آنها در همان مسیر، جان خود را که جان جهان و خلقت بود، تقدیم کردند.</p>\r\n\r\n<p>خداوندا ! تو را شکرگزارم که پس از عبد صالحت خمینی عزیز، مرا در مسیر عبد صالح دیگری که مظلومیتش اعظم است بر صالحیتش، مردی که حکیم امروز اسلام و تشیّع و ایران و جهان سیاسی اسلام است، خامنه&zwnj;ای عزیز ــ که جانم فدای جان او باد ــ قرار دادی.</p>\r\n\r\n<p>پروردگارا ! تو را سپاس که مرا با بهترین بندگانت در هم آمیختی و درک بوسه بر گونه&zwnj;های بهشتی آنان و استشمام بوی عطر الهی آنان را ـ یعنی مجاهدین و شهدای این راه ـ به من ارزانی داشتی.</p>\r\n\r\n<p>خداوندا! ای قادر عزیز و ای رحمان رزّاق، پیشانی شکر شرم بر آستانت می&zwnj;سایم که مرا در مسیر فاطمه اطهر و فرزندانش در مذهب تشیّع، عطر حقیقی اسلام، قرار دادی و مرا از اشک بر فرزندان علی&zwnj;بن ابی&zwnj;طالب و فاطمه اطهر بهره&zwnj;مند نمودی؛ چه نعمت عظمایی که بالاترین و ارزشمندترین نعمتهایت است؛ نعمتی که در آن نور است، معنویت، بیقراری که در درون خود بالاترین قرارها را دارد، غمی که آرامش و معنویت داد.</p>\r\n\r\n<p>خداوندا، تو را سپاس که مرا از پدر و مادر فقیر، اما متدیّن و عاشق اهل&zwnj;بیت و پیوسته در مسیر پا کی بهره&zwnj;مند نمودی. از تو عاجزانه می&zwnj;خواهم آنها را در بهشتت و با اولیائت قرین کنی و مرا در عالم آخرت از درک محضرشان بهره&zwnj;مند فرما.</p>\r\n\r\n<p><strong>خدایا! به عفو تو امید دارم</strong></p>\r\n\r\n<p>ای خدای عزیز و ای خالق حکیم بی&zwnj;همتا ! دستم خالی است و کوله&zwnj;پشتی سفرم خالی، من بدون برگ و توشه&zwnj;ای به&zwnj;امید ضیافت عفو و کرم تو می&zwnj;آیم. من توشه&zwnj;ای برنگرفته&zwnj;ام؛ چون فقیر [را] در نزد کریم چه حاجتی است به توشه و برگ؟!</p>\r\n\r\n<p>سارُق، چارُقم پر است از امید به تو و فضل و کرم تو؛ همراه خود دو چشم بسته آورده&zwnj;ام که ثروت آن در کنار همه ناپاکی&zwnj;ها، یک ذخیره ارزشمند دارد و آن گوهر اشک بر حسین فاطمه است؛ گوهر اشک بر اهل&zwnj;بیت است؛ گوهر اشک دفاع از مظلوم، یتیم، دفاع از محصورِ مظلوم در چنگ ظالم.</p>\r\n\r\n<p>خداوندا! در دستان من چیزی نیست؛ نه برای عرضه [چیزی دارند] و نه قدرت دفاع دارند، اما در دستانم چیزی را ذخیره کرده&zwnj;ام که به این ذخیره امید دارم و آن روان بودن پیوسته به&zwnj;سمت تو است. وقتی آنها را به&zwnj;سمتت بلند کردم، وقتی آنها را برایت بر زمین و زانو گذاردم، وقتی سلاح را برای دفاع از دینت به دست گرفتم؛ اینها ثروتِ دست من است که امید دارم قبول کرده باشی. خداوندا! پاهایم سست است، رمق ندارد. جرأت عبور از پلی که از جهنّم عبور می&zwnj;کند، ندارد. من در پل عادی هم پاهایم می&zwnj;لرزد، وای بر من و صراط تو که از مو نازک&shy;تر است و از شمشیر بُرنده&zwnj;تر؛ اما یک امیدی به من نوید می&zwnj;دهد که ممکن است نلرزم، ممکن است نجات پیدا کنم. من با این پاها در حَرَمت پا گذارده&zwnj;ام دورِ خانه&zwnj;ات چرخیده&zwnj;ام و در حرم اولیائت در بین&zwnj;الحرمین حسین و عباست آنها را برهنه دواندم و این پاها را در سنگرهای طولانی، خمیده جمع کردم و در دفاع از دینت دویدم، جهیدم، خزیدم، گریستم، خندیدم و خنداندم و گریستم و گریاندم؛ افتادم و بلند شدم. امید دارم آن جهیدن&zwnj;ها و خزیدن&zwnj;ها و به حُرمت آن حریم&zwnj;ها، آنها را ببخشی.</p>\r\n\r\n<p>خداوندا! سر من، عقل من، لب من، گوش من، قلب من، همه اعضا و جوارحم در همین امید به&zwnj;سر می&zwnj;برند؛ یا ارحم الراحمین! مرا بپذیر؛ پاکیزه بپذیر؛ آن&zwnj;چنان بپذیر که شایسته دیدارت شوم. جز دیدار تو را نمی&zwnj;خواهم، بهشت من جوار توست، یا الله!</p>\r\n\r\n<p><strong>خدایا! از کاروان دوستانم جامانده&zwnj;ام</strong></p>\r\n\r\n<p>خداوند، ای عزیز! من سال&zwnj;ها است از کاروانی به&zwnj;جا مانده&zwnj;ام و پیوسته کسانی را به&zwnj;سوی آن روانه می&zwnj;کنم، اما خود جا مانده&zwnj;ام، اما تو خود می&zwnj;دانی هرگز نتوانستم آنها را از یاد ببرم. پیوسته یاد آنها، نام آنها، نه در ذهنم بلکه در قلبم و در چشمم، با اشک و آه یاد شدند.</p>\r\n\r\n<p>عزیز من! جسم من در حال علیل شدن است. چگونه ممکن [است] کسی که چهل سال بر درت ایستاده است را نپذیری؟ خالق من، محبوب من، عشق من که پیوسته از تو خواستم سراسر وجودم را مملو از عشق به خودت کنی؛ مرا در فراق خود بسوزان و بمیران.</p>\r\n\r\n<p>عزیزم! من از بی&zwnj;جاقراری و رسوای ماندگی، سر به بیابان&zwnj;ها گذارده&zwnj;ام؛ من به&zwnj;امیدی از این شهر به آن شهر و از این صحرا به آن صحرا در زمستان و تابستان می&zwnj;روم. کریم، حبیب، به کَرَمت دل بسته&zwnj;ام، تو خود می&zwnj;دانی دوستت دارم. خوب می&zwnj;دانی جز تو را نمی&zwnj;خواهم. مرا به خودت متصل کن.</p>\r\n\r\n<p>خدایا وحشت همه وجودم را فرا گرفته است. من قادر به مهار نفس خود نیستم، رسوایم نکن. مرا به&zwnj;حرمت کسانی که حرمتشان را بر خودت واجب کرده&zwnj;ای، قبل از شکستن حریمی که حرم آنها را خدشه&zwnj;دار می&zwnj;کند، مرا به قافله&zwnj;ای که به&zwnj;سویت آمدند، متصل کن.</p>\r\n\r\n<p>معبود من، عشق من و معشوق من، دوستت دارم. بارها تو را دیدم و حس کردم، نمی&zwnj;توانم از تو جدا بمانم. بس است، بس. مرا بپذیر، اما آن&zwnj;چنان که شایسته تو باشم.</p>\r\n\r\n<p><strong>خطاب به برادران و خواهران مجاهدم...</strong></p>\r\n\r\n<p>خواهران و برادران مجاهدم در این عالم، ای کسانی که سرهای خود را برای خداوند عاریه داده&zwnj;اید و جان&zwnj;ها را بر کف دست گرفته و در بازار عشق&zwnj;بازی به سوق فروش آمده&zwnj;اید، عنایت کنید: جمهوری اسلامی، مرکز اسلام و تشیّع است.</p>\r\n\r\n<p>امروز قرارگاه حسین&zwnj;بن علی، ایران است. بدانید جمهوری اسلامی حرم است و این حرم اگر ماند، دیگر حرم&zwnj;ها می&zwnj;مانند. ا گر دشمن، این حرم را از بین برد، حرمی باقی نمی&zwnj;ماند، نه حرم ابراهیمی و نه حرم محمّدی(ص).</p>\r\n\r\n<p>برادران و خواهرانم! جهان اسلام پیوسته نیازمند رهبری است؛ رهبری متصل به و منصوب شرعی و فقهی معصوم. خوب می&zwnj;دانید منزّه&zwnj;ترین عالِم دین که جهان را تکان داد اسلام را احیا کرد، یعنی خمینی بزرگ و پاک ما، ولایت فقیه را تنها نسخه نجات&zwnj;بخش این امت قرار داد؛ لذا چه شما که به&zwnj;عنوان شیعه به آن اعتقاد دینی دارید و چه شما به&zwnj;عنوان سنّی اعتقاد عقلی دارید، بدانید [باید] به&zwnj;دور از هرگونه اختلاف، برای نجات اسلام خیمه ولایت را رها نکنید. خیمه، خیمه رسول&zwnj;الله است. اساس دشمنی جهان با جمهوری اسلامی، آتش زدن و ویران کردن این خیمه است، دور آن بچرخید. والله والله والله این خیمه اگر آسیب دید، بیت الله الحرام و مدینه حرم رسول الله و نجف، کربلا، کاظمین، سامرا و مشهد باقی نمی&zwnj;ماند؛ قرآن آسیب می&zwnj;بیند.</p>\r\n\r\n<p><strong>خطاب به برادران و خواهران ایرانی...</strong></p>\r\n\r\n<p>برادران و خواهران عزیز ایرانی من، مردم پرافتخار و سربلند که جان من و امثال من، هزاران بار فدای شما باد، کما اینکه شما صدها هزار جان را فدای اسلام و ایران کردید؛ از اصول مراقبت کنید، اصول یعنی ولیّ فقیه، خصوصاً این حکیم، مظلوم، وارسته در دین، فقه، عرفان، معرفت؛ خامنه&zwnj;ای عزیز را جان خود بدانید، حرمت او را مقدسات بدانید.</p>\r\n\r\n<p><strong>برادران و خواهران، پدران و مادران، عزیزان من!</strong></p>\r\n\r\n<p>جمهوری اسلامی، امروز سربلندترین دوره خود را طی می&zwnj;کند. بدانید مهم نیست که دشمن چه نگاهی به شما دارد، دشمن به پیامبر شما چه نگاهی داشت و [دشمنان&zwnj;] چگونه با پیامبر خدا و اولادش عمل کردند، چه اتهاماتی به او زدند، چگونه با فرزندان مطهر او عمل کردند؟ مذمت دشمنان و شماتت آنها و فشار آنها، شما را دچار تفرقه نکند.</p>\r\n\r\n<p>بدانید که می&zwnj;دانید مهمترین هنر خمینی عزیز این بود که اول اسلام را به پشتوانه ایران آورد و سپس ایران را در خدمت اسلام قرار داد. اگر اسلام نبود و اگر روح اسلامی بر این ملت حاکم نبود، صدام چون گرگ درنده&zwnj;ای این کشور را می&zwnj;درید؛ آمریکا چون سگ هاری همین عمل را می&zwnj;کرد، اما هنر امام این بود که اسلام را پشتوانه آورد؛ عاشورا و محرّم، صفر و فاطمیه را به پشتوانه این ملت آورد، انقلاب&zwnj;هایی در انقلاب ایجاد کرد، به این دلیل در هر دوره هزاران فداکار جان خود را سپر شما و ملت ایران و خاک ایران و اسلام نموده&zwnj;اند و بزرگترین قدرت&zwnj;های مادی را ذلیل خود نموده&zwnj;اند. عزیزانم، در اصول اختلاف نکنید.</p>\r\n\r\n<p>شهدا، محور عزّت و کرامت همه ما هستند؛ نه برای امروز، بلکه همیشه اینها به دریای واسعه خداوند سبحان اتصال یافته&zwnj;اند. آنها را در چشم، دل و زبان خود بزرگ ببینید، همان&zwnj;گونه که هستند. فرزندانتان را با نام آنها و تصاویر آنها آشنا کنید. به فرزندان شهدا که یتیمان همه شما هستند، به&zwnj;چشم ادب و احترام بنگرید. به همسران و پدران و مادران آنان احترام کنید، همان&zwnj;گونه که از فرزندان خود با اغماض می&zwnj;گذرید، آنها را در نبود پدران، مادران، همسران و فرزندان خود توجه خاص کنید.</p>\r\n\r\n<p>نیروهای مسلّح خود را که امروز ولی فقیه فرمانده آنان است، برای دفاع از خودتان، مذهبتان، اسلام و کشور احترام کنید و نیروهای مسلح می&zwnj;بایست همانند دفاع از خانه خود، از ملت و نوامیس و ارضِ آن حفاظت و حمایت و ادب و احترام کنند و نسبت به ملت همان&zwnj;گونه که امیرالمؤمنین مولای متقیان فرمود، نیروهای مسلح می&zwnj;بایست منشأ عزت ملت باشد و قلعه و پناهگاه مستضعفین و مردم باشد و زینت کشورش باشد.</p>\r\n\r\n<p><strong>خطاب به مردم عزیز کرمان...</strong></p>\r\n\r\n<p>نکته&zwnj;ای هم خطاب به مردم عزیز کرمان دارم؛ مردمی که دوست&zwnj;داشتنی&zwnj;اند و در طول 8 سال دفاع مقدس بالاترین فداکاری&zwnj;ها را انجام دادند و سرداران و مجاهدین بسیار والامقامی را تقدیم اسلام نمودند. من همیشه شرمنده آنها هستم. هشت سال به&zwnj;خاطر اسلام به من اعتماد کردند؛ فرزندان خود را در قتلگاه&zwnj;ها و جنگ&zwnj;های شدیدی چون کربلای5، والفجر8، طریق&zwnj;القدس، فتح&zwnj;المبین، بیت&zwnj;المقدس و... روانه کردند و لشکری بزرگ و ارزشمند را به نام و به عشق امام مظلوم حسین&zwnj;بن علی به نام ثارالله، بنیانگذاری کردند. این لشکر همچون شمشیری برنده، بارها قلب ملت&zwnj;مان و مسلمان&zwnj;ها را شاد نمود و غم را از چهره آنها زدود. عزیزان! من بنا به تقدیر الهی امروز از میان شما رفته&zwnj;ام. من شما را از پدر و مادرم و فرزندان و خواهران و برادران خود بیشتر دوست دارم، چون با شما بیشتر از آنها بودم؛ ضمن اینکه من پاره&zwnj;تن آنها بودم و آنها پاره وجود من، اما آنها هم قبول کردند من وجودم را نذر وجود شما و ملت ایران کنم.</p>\r\n\r\n<p>دوست دارم کرمان همیشه و تا آخر با ولایت بماند. این ولایت، ولایت علی&zwnj;بن ابی&zwnj;طالب است و خیمه او خیمه حسین فاطمه است، دور آن بگردید. با همه شما هستم. می&zwnj;دانید در زندگی به انسانیت و عاطفه&zwnj;ها و فطرت&zwnj;ها بیشتر از رنگ&zwnj;های سیاسی توجه کردم. خطاب من به همه شما است که مرا از خود می&zwnj;دانید، برادر خود و فرزند خود می&zwnj;دانید.</p>\r\n\r\n<p>وصیت می&zwnj;کنم اسلام را در این برهه که تداعی&zwnj;یافته در انقلاب اسلامی و جمهوری اسلامی است، تنها نگذارید. دفاع از اسلام نیازمند هوشمندی و توجه خاص است. در مسائل سیاسی آنجا که بحث اسلام، جمهوری اسلامی، مقدسات و ولایت فقیه مطرح می&zwnj;شود، اینها رنگ خدا هستند؛ رنگ خدا را بر هر رنگی ترجیح دهید.</p>\r\n\r\n<p><strong>خطاب به خانواده شهدا...</strong></p>\r\n\r\n<p>فرزندانم، دختران و پسرانم، فرزندان شهدا، پدران و مادران باقی&zwnj;مانده از شهدا، ای چراغ&zwnj;های فروزان کشور ما، خواهران و برادران و همسران وفادار و متدینه شهدا! در این عالم، صوتی که روزانه من می&zwnj;شنیدم و مأنوس با آن بودم و همچون صوت قرآن به من آرامش می&zwnj;داد و بزرگترین پشتوانه معنوی خود می&zwnj;دانستم، صدای فرزندان شهدا بود که بعضاً روزانه با آن مأنوس بودم؛ صدای پدر و مادر شهدا بود که وجود مادر و پدرم را در وجودشان احساس می&zwnj;کردم.</p>\r\n\r\n<p>عزیزانم! تا پیشکسوتان این ملتید، قدر خودتان را بدانید. شهیدتان را در خودتان جلوه&zwnj;گر کنید، به&zwnj;طوری که هر کس شما را می&zwnj;بیند، پدر شهید یا فرزند شهید را، بعینه خوِد شهید را احساس کند، با همان معنویت، صلابت و خصوصیت.</p>\r\n\r\n<p>خواهش می&zwnj;کنم مرا حلال کنید و عفو نمایید. من نتوانستم حق لازم را پیرامون خیلی از شماها و حتی فرزندان شهیدتان ادا کنم، هم استغفار می&zwnj;کنم و هم طلب عفو دارم.</p>\r\n\r\n<p>دوست دارم جنازه&zwnj;ام را فرزندان شهدا بر دوش گیرند، شاید به&zwnj;برکت اصابت دستان پاک آنها بر جسدم، خداوند مرا مورد عنایت قرار دهد.</p>\r\n\r\n<p><strong>خطاب به سیاسیون کشور...</strong></p>\r\n\r\n<p>نکته&zwnj;ای کوتاه خطاب به سیاسیون کشور دارم: چه آنهایی [که] اصلاح&zwnj;طلب خود را می&zwnj;نامند و چه آنهایی که اصولگرا. آنچه پیوسته در رنج بودم این&zwnj;که عموماً ما در دو مقطع، خدا و قرآن و ارزش&zwnj;ها را فراموش می&zwnj;کنیم، بلکه فدا می&zwnj;کنیم. عزیزان، هر رقابتی با هم می&zwnj;کنید و هر جدلی با هم دارید، اما اگر عمل شما و کلام شما یا مناظره&zwnj;هایتان به&zwnj;نحوی تضعیف&zwnj;کننده دین و انقلاب بود، بدانید شما مغضوب نبی مکرم اسلام و شهدای این راه هستید؛ مرزها را تفکیک کنید. اگر می&zwnj;خواهید با هم باشید، شرط با هم بودن، توافق و بیان صریح حول اصول است. اصول، مطوّل و مفصّل نیست. اصول عبارت از چند اصل مهم است:</p>\r\n\r\n<p>اول آنها، اعتقاد عملی به ولایت فقیه است؛ یعنی این که نصیحت او را بشنوید، با جان و دل به توصیه و تذکرات او به&zwnj;عنوان طبیب حقیقی شرعی و علمی، عمل کنید. کسی که در جمهوری اسلامی می&zwnj;خواهد مسئولیتی را احراز کند، شرط اساسی آن [این است که] اعتقاد حقیقی و عمل به ولایت فقیه داشته باشد. من نه می&zwnj;گویم ولایت تنوری و نه می&zwnj;گویم ولایت قانونی؛ هیچ یک از این دو، مشکل وحدت را حل نمی&zwnj;کند؛ ولایت قانونی، خاصّ عامه مردم اعم از مسلم و غیرمسلمان است، اما ولایت عملی مخصوص مسئولین است که می&zwnj;خواهند بار مهم کشور را بر دوش بگیرند، آن هم کشور اسلامی با این همه شهید!</p>\r\n\r\n<p>اعتقاد حقیقی به جمهوری اسلامی و آنچه مبنای آن بوده است؛ از اخلاق و ارزش&zwnj;ها تا مسئولیت&zwnj;ها؛ چه مسئولیت در قبال ملت و چه در قبال اسلام.</p>\r\n\r\n<p>به&zwnj;کارگیری افراد پاکدست و معتقد و خدمتگزاری به ملّت، نه افرادی که حتی اگر به میز یک دهستان هم برسند خاطره&zwnj; خان&zwnj;های سابق را تداعی می&zwnj;کنند.</p>\r\n\r\n<p>مقابله با فساد و دوری از فساد و تجمّلات را شیوه خود قرار دهند.</p>\r\n\r\n<p>در دوره حکومت و حاکمیت خود در هر مسئولیتی، احترام به مردم و خدمت به آنان را عبادت بدانند و خود خدمتگزار واقعی، توسعه&zwnj;گر ارزش&zwnj;ها باشند، نه با توجیهات واهی، ارزشها را بایکوت کنند.</p>\r\n\r\n<p>مسئولین همانند پدران جامعه می&zwnj;بایست به مسئولیت خود پیرامون تربیت و حراست از جامعه توجه کنند، نه با بی&zwnj;مبالاتی و به&zwnj;خاطر احساسات و جلب برخی از آرای احساسی زودگذر، از اخلاقیاتی حمایت کنند که طلاق و فساد را در جامعه توسعه دهد و خانواده&zwnj;ها را از هم بپاشاند. حکومت&zwnj;ها عامل اصلی در استحکام خانواده و از طرف دیگر عامل مهم از هم پاشیدن خانواده هستند. اگر به اصول عمل شد، آن وقت همه در مسیر رهبر و انقلاب و جمهوری اسلامی هستند و یک رقابت صحیح بر پایه همین اصول برای انتخاب اصلح صورت می&zwnj;گیرد.</p>\r\n\r\n<p><strong>خطاب به برادران سپاهی و ارتشی...</strong></p>\r\n\r\n<p>کلامی کوتاه خطاب به برادران سپاهی عزیز و فداکار و ارتشی&zwnj;های سپاهی دارم: ملاک مسئولیت&zwnj;ها را برای انتخاب فرماندهان، شجاعت و قدرت اداره بحران قرار دهید. طبیعی است به ولایت اشاره نمی&zwnj;کنم، چون ولایت در نیروهای مسلح جزء نیست، بلکه اساس بقای نیروهای مسلح است، این شرط خلل&zwnj;ناپذیر می&zwnj;باشد.</p>\r\n\r\n<p>نکته دیگر، شناخت بموقع از دشمن و اهداف و سیاست&zwnj;های او و اخذ تصمیم بموقع و عمل بموقع؛ هر یک از اینها اگر در غیر وقت خود صورت گیرد، بر پیروزی شما اثر جدّی دارد.</p>\r\n\r\n<p><strong>خطاب به علما و مراجع معظم...</strong></p>\r\n\r\n<p>سخنی کوتاه از یک سرباز 40 ساله در میدان، به علمای عظیم&zwnj;الشأن و مراجع گران&zwnj;قدر که موجب روشنایی جامعه و سبب زدودن تاریکی مراجع عظام تقلید؛ سربازتان از یک برج دیده&zwnj;بانی دید که اگر این نظام آسیب ببیند، دین و آنچه از ارزش&zwnj;های آن [که] شما در حوزه&zwnj;ها استخوان خُرد کرده&zwnj;اید و زحمت کشیده&zwnj;اید، از بین می&zwnj;رود.</p>\r\n\r\n<p>این دوره&zwnj;ها با همه دوره&zwnj;ها متفاوت است، این بار اگر مسلّط شدند، از اسلام چیزی باقی&zwnj;نمی&zwnj;ماند. راه صحیح، حمایت بدون هرگونه ملاحظه از انقلاب، جمهوری اسلامی و ولی فقیه است.</p>\r\n\r\n<p>نباید در حوادث، دیگران شما را که امید اسلام هستید به ملاحظه بیندازند. همه شما امام را دوست داشتید و معتقد به راه او بودید. راه امام مبارزه با آمریکا و حمایت از جمهوری اسلامی و مسلمانان تحت ستم استکبار، تحت پرچم ولی فقیه است.</p>\r\n\r\n<p>من با عقل ناقص خود می&zwnj;دیدم برخی خنّاسان سعی داشتند و دارند که مراجع و علمای مؤثر در جامعه را با سخنان خود و حالت حق&zwnj;به&zwnj;جانبی به سکوت و ملاحظه بکشانند. حق واضح است؛ جمهوری اسلامی و ارزش&zwnj;ها و ولایت فقیه میراث امام خمینی (رحمة الله علیه) هستند و می&zwnj;بایست مورد حمایت جدی قرار گیرند. من حضرت آیت&zwnj;الله&zwnj;العظمی خامنه&zwnj;ای را خیلی مظلوم و تنها می&zwnj;بینم. او نیازمند همراهی و کمک شماست و شما حضرات با بیانتان و دیدارهای&zwnj;تان و حمایت&zwnj;های&zwnj;تان با ایشان می&zwnj;بایست جامعه را جهت دهید. اگر این انقلاب آسیب دید، حتی زمان شاه ملعون هم نخواهد بود، بلکه سعی استکبار بر الحادگری محض و انحراف عمیق غیر قابل برگشت خواهد بود.</p>\r\n\r\n<p>دست مبارکتان را می&zwnj;بوسم و عذرخواهی می&zwnj;کنم از این بیان، اما دوست داشتم در شرف&zwnj;یابی&zwnj;های حضوری به محضرتان عرض کنم که توفیق حاصل نشد.</p>\r\n\r\n<p>سربازتان و دست&zwnj; بوستان</p>\r\n\r\n<p><strong>از همه طلب عفو دارم...</strong></p>\r\n\r\n<p>از همسایگانم و دوستانم و همکارانم طلب بخشش و عفو دارم. از رزمندگان لشکر ثارالله و نیروی باعظمت قدس که خار چشم دشمن و سدّ راه او است، طلب بخشش و عفو دارم؛ خصوصاً از کسانی که برادرانه به من کمک کردند.</p>\r\n\r\n<p>نمی&zwnj;توانم از حسین پورجعفری نام نبرم که خیرخواهانه و برادرانه مرا مثل فرزندی کمک می&zwnj;کرد و مثل برادرانم دوستش داشتم. از خانواده ایشان و همه برادران رزمنده و مجاهدم که به زحمت انداختمشان عذرخواهی می&zwnj;کنم. البته همه برادران نیروی قدس به من محبّت برادرانه داشته و کمک کردند و دوست عزیزم سردارقاآنی که با صبر و متانت مرا تحمل کردند.</p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>آخرین دست نوشته حاج قاسم سلیمان دو سه ساعت قبل از شهادتش در سوریه پنجشنبه:</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>&laquo;الهی لا تکلنی</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>خداوندا مرا بپذیر</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>خداوندا عاشق دیدارتم</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>همان دیداری که موسی را ناتوان از ایستادن و نفس کشیدن نمود</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>خداوندا مرا پاکیزه بپذیر</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>الحمدلله رب العالمین</strong></span></p>\r\n\r\n<p><span style=\"color:#e74c3c\"><strong>خداوندا مرا پاکیزه بپذیر&raquo;</strong></span></p>\r\n\r\n<p><strong>۹۸/۱۰/۱۲</strong></p>\r\n', '1404-02-06 02:04'),
(12, 'شهید الیاس اکبری', 'imgs/vasiatnameh_shohada/IMG_20250519_142354_323_Opx2yTZ.jpg', '<p><strong><span style=\"color:#c0392b\">بسم رب الشهداء و الصدیقین</span></strong></p>\r\n\r\n<p>شهید الیاس اکبری متولد ۱۳۶۲ در یکی از روستاهای آمل در یک خانواده متدیّن به دنیا آمده، ایشان در همان سن کودکی مورد علاقه خانواده و اطرافیان بود، به پدر و مادر و خانواده&zwnj;اش خیلی احترام می&zwnj;گذاشت و به همه محبت می&zwnj;کرد و در کار زمین به پدرش کمک می&zwnj;کرد و چون خیلی مهربان و دوست داشتنی بود همه فامیل او را دوست می&zwnj;داشتند او خیلی شوخ طبع بود همیشه نمازش را اول وقت می&zwnj;خواند و به قرآن خواندن خیلی اهمیت می&zwnj;داد و چند بار در طول عمر کوتاه&zwnj;اش قرآن و هدایای مختلف جایزه می&zwnj;گرفت و در مدرسه حتی تا ديپلمش شاگرد اول بود.</p>\r\n\r\n<p><strong>خواهر شهید</strong></p>\r\n\r\n<p>برادرم روبوسی با دیگران را زیاد دوست نمی داشت هر وقت میخواستم با او روبوسی کنم چشمانش را می بست و روبوسی نمی&zwnj;کرد تا اینکه برای آخرین بار میخواست به سربازی برود وقتی که صورت ماهش را بوسیدم او هم صورتم را بوسید و همان جا به دلم افتاد که برادرم دیگر بر&zwnj;نمی&zwnj;گردد و در همان آخرین دیدار تصبیحش را در خانه&zwnj;ام جا گذاشت و آخرین حرفی که با من زد؛ گفت این دفعه تصبیحم را بیاور و آن تصبیح تنها یادگاری او برای من شد.</p>\r\n\r\n<p>او در سن ۲۰ سالگی در سنندج به شهادت رسید، نامش گرامی و یادش پایدار باد.</p>\r\n', '1404-02-29 14:51');

